(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["de"] = {"ui":{"lead":"Menschen haben Spiele nicht nur gespielt, sondern auch gemalt. Vergrößere 3300 Jahre Bilder und Figuren und entdecke die Details.","details":"Details","links":"Das Spiel ansehen oder spielen","record":"Zum Werk","game":"Spiel","exhibit":"Sammlung","room":"Saal","room_chance":"Zufall","hint":"Zum Zoomen ziehen oder scrollen · zum Verschieben ziehen · eine Nummer antippen","r_artist":"Künstler","r_date":"Datierung","r_place":"Ort","r_medium":"Technik","r_size":"Maße","r_museum":"Museum","r_credit":"Erwerb","r_rights":"Bild","met":"The Metropolitan Museum of Art","cc0":"Open Access (gemeinfrei)","metlink":"Das Werk auf der Website des Museums","credit":"Bilder: The Metropolitan Museum of Art, The Cleveland Museum of Art, The Art Institute of Chicago und das Rijksmuseum, Open Access (gemeinfrei).","cma":"The Cleveland Museum of Art","aic":"The Art Institute of Chicago","rijks":"Rijksmuseum, Amsterdam"},"nefertari":{"title":"Königin Nefertari beim Senet","artist":"Nina de Garis Davies (Faksimile)","date":"Original um 1290–1224 v. Chr. · Faksimile 1921–22","place":"Ägypten (Tal der Königinnen)","game":"Senet","medium":"Tempera auf Papier (Faksimile in halber Größe)","p":["Nefertari war die große königliche Gemahlin Ramses’ II. Dies ist die Kopie eines Gemäldes aus ihrem Grab im Tal der Königinnen, 1921–22 im Grab selbst angefertigt; sogar die Risse und Fehlstellen der Wand wurden mitkopiert.","Die Königin sitzt vor einem Brett und spielt Senet gegen einen unsichtbaren Gegner. In einem Grab gemalt, bedeutete das Spiel vermutlich mehr als Zeitvertreib: den Weg ins Jenseits zu gewinnen."],"spots":[["Zwei Arten von Steinen","Spitze Steine und spulenförmige Steine stehen auf dem Brett: je ein Satz für jeden Spieler."],["Die Hand der Königin","Ihre Finger greifen nach einem Stein."],["Brett und Gestell","Das Brett ist von der Seite gezeigt, darum sieht man die Felder nicht. Es ruht auf einem schmalbeinigen Gestell."],["Ihr Name","Der Name der Königin steht in einem Oval, einer Kartusche."],["Der unsichtbare Gegner","Niemand sitzt ihr gegenüber: Sie spielt gegen einen Gegner, den man nicht sieht."]]},"hydria":{"title":"Achill und Aias beim Brettspiel (Hydria)","artist":"Der Leagros-Gruppe zugeschrieben","date":"um 510 v. Chr.","place":"Griechenland (Attika)","game":"Ein Würfelspiel","medium":"Terrakotta (schwarzfigurig)","p":["Während der Belagerung Trojas vertreiben sich zwei griechische Helden, Achill und Aias, die Zeit an einem Brett. Erfunden hat die Szene um 540 v. Chr. der Töpfer und Maler Exekias; sein Original ist auf einer Amphora in den Vatikanischen Museen erhalten.","Das Thema war zwischen etwa 540 und 480 v. Chr. sehr beliebt; über 150 Beispiele sind bekannt. Auf dieser Hydria steht die Göttin Athena in der Mitte. Die Helden spielen ein Spiel, bei dem die Steine nach dem Wurf der Würfel ziehen."],"spots":[["Athena","Die Göttin Athena steht zwischen den beiden."],["Der Held links","Den Speer noch in der Hand, beugt er sich über das Brett."],["Der Held rechts","Auch er hat die Waffen nicht abgelegt: ein Augenblick Spiel mitten im Krieg."],["Das Brett","Der niedrige Block zwischen ihnen ist das Brett."],["Die Schulter","Auf der Schulter des Gefäßes fährt ein Wagen los."]]},"liubo":{"title":"Zwei sitzende Figuren beim Liubo","date":"1. Jh. v. Chr. – 1. Jh. n. Chr.","place":"China (Han-Dynastie)","game":"Liubo","medium":"Bemalte Irdenware","p":["Zwei Liubo-Spieler – Liubo war die große Mode im China der Han-Zeit. Solche Figuren gab man ins Grab mit dem Wunsch, dass die Freuden des Lebens nach dem Tod weitergehen.","Auf dem Foto liegen das Liubo-Brett und die Knochensteine aus der Sammlung dieses Museums zwischen ihnen. Die Figuren halten einen dramatischen Augenblick einer hitzigen Partie fest."],"spots":[["Das Liubo-Brett","Dasselbe Brett wie „Liubo-Brett mit Steinen“ in der Sammlung: Siehe die T-, L- und V-Zeichen."],["Der Spieler links","Er betrachtet das Brett in aller Ruhe."],["Der Spieler rechts","Die Hand erhoben, der Mund weit offen: Ist ihm gerade der entscheidende Zug gelungen?"],["Steine auf dem Brett","Knochensteine stehen an beiden Enden des Bretts."],["Steine neben dem Brett","Weitere Steine liegen auf dem Boden."]]},"shahnama":{"title":"„Buzurjmihr ergründet das indische Schachspiel“, aus dem Schahname des Schah Tahmasp","artist":"Malerei ʿAbd al-Vahhab zugeschrieben","date":"um 1530–35","place":"Iran (Täbris)","game":"Schach","medium":"Deckfarben, Tinte, Silber und Gold auf Papier","p":["Eine Szene aus Firdausis Epos, dem Schahname (Buch der Könige). Der König von Indien schickt einen Gesandten mit Schachbrett und Figuren und fordert den persischen König Nuschirwan heraus: Findet er heraus, wie das Spiel geht, zahlt Indien Tribut.","Nur der junge Weise Buzurjmihr löst das Rätsel rechtzeitig. Im Schahname schickt Persien zum Dank das Backgammon zurück, und die Inder können es nicht lösen. König und Höflinge starren auf das Brett und die Spieler."],"spots":[["Das Schachbrett","Die Figuren stehen auf einem karierten Brett, so klein, dass man ihre Formen kaum erkennt."],["König Nuschirwan","Auf seinem Thron wartet er auf die Lösung des Rätsels."],["Rund um das Brett","Die Spieler beugen sich über das Brett."],["Die Verse","Die Felder oben und unten tragen Verse Firdausis."],["Die Höflinge","Männer mit Turbanen mit hohen roten Stäben sehen stehend zu."]]},"chaupar":{"title":"Shiva und Parvati beim Chaupar, aus einer Rasamanjari-Serie","artist":"Devidasa von Nurpur","date":"1694–95","place":"Indien (Basohli, Jammu)","game":"Chaupar (verwandt mit dem Vorfahren von Ludo)","medium":"Deckfarben, Tinte, Silber und Gold auf Papier","p":["Ein Blatt aus einer Serie zur Rasamanjari, einem Sanskrit-Liebesgedicht des 15. Jahrhunderts. Der Gott Shiva und seine Gemahlin Parvati sitzen auf einem Tigerfell um ein kreuzförmiges Brett.","Shiva hat Parvati gerade mit einem Trick eine Halskette abgenommen, und sie fleht ihn an. Kühne Farben, eine unbestimmte Raumtiefe, Farbe und Geste mit Bedeutung: Das sind die Kennzeichen der Basohli-Schule."],"spots":[["Das kreuzförmige Brett","Chaupar und Pachisi spielt man auf einem Brett in dieser Kreuzform."],["Weiße Stäbe auf dem Brett","Wohl die langen Würfel (Pasa) des Chaupar."],["Shiva","Weiß am Körper, eine Schlange um den Hals."],["Parvati","Mit ausgestreckter Hand bittet sie um ihre Kette."],["Das Tigerfell","Beide sitzen auf einem Tigerfell."]]},"shogi":{"title":"Junge Frau und junger Mann beim Shōgi („Chūnagon Kanesuke“, aus den Sechsunddreißig Unsterblichen der Dichtkunst)","artist":"Suzuki Harunobu","date":"um 1767–69","place":"Japan (Edo)","game":"Shogi","medium":"Farbholzschnitt (Nishiki-e)","p":["Ein Blatt aus einer Serie, die auf die Sechsunddreißig Unsterblichen der Dichtkunst anspielt; dieses steht für den Dichter Chūnagon Kanesuke. In einer Sommernacht sitzen eine junge Frau und ein junger Mann neben einem Moskitonetz am Shogibrett.","Harunobu war der Künstler, der den vielfarbigen, mit vielen Druckstöcken gedruckten Holzschnitt populär machte. Selbst die Steine auf dem Brett sind genau gezeichnet."],"spots":[["Ein Shogibrett auf Füßen","Ein dickes Brett auf Füßen, wie man es heute noch hat."],["Ein Kästchen","Wohl das Kästchen für die Steine."],["Das Moskitonetz","Ein grünes Moskitonetz hängt im Raum: Es ist eine Sommernacht."],["Die Laterne","Eine Standlampe beleuchtet das Brett."],["Das Gedicht","Das wolkenförmige Feld trägt den Namen des Dichters und ein Gedicht."]]},"sugoroku":{"title":"Zwei junge Frauen beim Sugoroku","artist":"Utagawa Toyokuni I.","date":"Edo-Zeit (spätes 18. – frühes 19. Jh.)","place":"Japan (Edo)","game":"Ban-Sugoroku (verwandt mit Backgammon)","medium":"Diptychon aus Farbholzschnitten","p":["Zwei Holzschnitte, zu einem breiten Bild zusammengesetzt: Junge Frauen in einem Zimmer vergnügen sich beim Ban-Sugoroku. Das Spiel ist ein Verwandter des Backgammon, aus derselben Linie wie das Sugoroku-Brett aus dem Shōsōin in dieser Sammlung.","Weiße und schwarze Steine stehen auf dem Brett, und die junge Frau rechts hält einen Becher zum Würfeln. Durch das Fenster sieht man den Fuji."],"spots":[["Das Brett","Weiße und schwarze Steine auf seinen langen Feldern."],["Der Würfelbecher","In ihm werden die Würfel geschüttelt."],["Steine neben dem Brett","Schon hinausgespielt oder noch nicht eingesetzt?"],["Der Fuji","Der Fuji jenseits des Fensters."],["Die Nahtstelle","Hier treffen die beiden Holzschnitte aufeinander."]]},"eakins":{"title":"Die Schachspieler","artist":"Thomas Eakins","date":"1876","place":"USA (Philadelphia)","game":"Schach","medium":"Öl auf Holz","p":["Im Salon eines Hauses in Philadelphia spielen zwei Freunde Schach, während der Vater des Künstlers, Benjamin Eakins, zusieht. Seinen sorgfältigen Raumaufbau und die genauen Details hatte Eakins bei seinem Pariser Lehrer Gérôme gelernt.","1881 wurde Die Schachspieler das erste Werk, das das Metropolitan Museum als Schenkung eines lebenden Künstlers annahm."],"spots":[["Die Schachfiguren","Im dämmrigen Raum leuchten die Figuren auf dem Brett im Licht auf."],["Der Vater des Künstlers","Stehend verfolgt er die Partie: Benjamin Eakins."],["Der Spieler rechts","Der Maler George W. Holmes, ein Freund des Vaters."],["Die Schublade","Eine lateinische Inschrift: „Benjamin Eakins’ Sohn malte dies im Jahr ’76.“"],["Über dem Kamin","Eine Reproduktion eines Gemäldes von Gérôme, Eakins’ Lehrer."],["Die Katze","Auf dem Boden scheint nur die Katze sich nicht für die Partie zu interessieren."]]},"weiqi":{"title":"Schale mit Unsterblichen beim Weiqi","artist":"Unbekannt","date":"1425–36 (Ming-Dynastie, Xuande-Ära)","place":"China","game":"Go (Weiqi)","medium":"Geschnitzter roter und grüner Lack","size":"H. 3,5; B. 14,9; L. 23,5 cm","credit":"Geschenk von Florence und Herbert Irving, 2015","p":["Eine Schale aus Schnitzlack: Dutzende Lackschichten wurden aufgetragen und dann geschnitzt; unter dem Rot liegt eine grüne Schicht, sodass die Schnitttiefe die Farben hervorholt. Im gelappten Rand spielen Unsterbliche unter einer Kiefer Go.","In China gibt es die Legende von Lanke, dem „verfaulten Axtstiel“: Der Holzfäller Wang Zhi sah in den Bergen Unsterblichen beim Go zu und merkte erst danach, dass so viel Zeit vergangen war, dass sein Axtstiel verfault war. Unsterbliche am Brett waren ein beliebtes Motiv. Wer die stehende Figur ist, sagen die Quellen nicht."],"spots":[["Das Brett","Das Go-Brett zwischen den beiden Unsterblichen, bis in die Linien geschnitzt."],["Die spielenden Unsterblichen","Zwei Gestalten sitzen bei den Felsen um das Brett."],["Die stehende Figur","Eine Figur steht etwas abseits. Sie erinnert an den Holzfäller der Legende, doch wer sie ist, ist unbekannt."],["Der Mond","Ein runder Mond am Himmel (oder vielleicht die Sonne)."],["Die Kiefer","Eine ausladende Kiefer, ein Baum, der oft für langes Leben und das Land der Unsterblichen steht."],["Der Päonienrand","Große Päonien und Blätter sind rund um den Rand geschnitzt."]]},"webb":{"title":"Die Backgammonspieler (Schrank)","artist":"Philip Webb (Entwurf), Edward Burne-Jones (Malerei), Morris, Marshall, Faulkner & Co. (Herstellung)","date":"1861","place":"Großbritannien (London)","game":"Backgammon","medium":"Bemaltes Kiefernholz, Öl auf Leder, Messing, Kupfer","size":"H. 185,4; B. 114,3; T. 53,3 cm","credit":"Rogers Fund, 1926","p":["Eines der frühesten Möbel der Firma, die William Morris 1861 mit Freunden gründete. Auf dem Leder der Türen sitzen ein Mann und eine Frau in mittelalterlicher Kleidung beim Backgammon, in Öl gemalt. Der Schrank wurde 1862 auf der Internationalen Ausstellung in London gezeigt.","Er fasst das Ziel der Arts-and-Crafts-Bewegung zusammen, die Grenze zwischen bildender und angewandter Kunst aufzuheben. Der Lederhintergrund ist mit winzigen Punkten gepunzt, einer mittelalterlichen Technik."],"spots":[["Das Brett","Das Backgammonbrett auf dem Tisch zwischen den beiden."],["Der Mann","Ein junger Mann, einen Stein in der Hand, betrachtet das Brett."],["Die Frau","Ihm gegenüber hält eine Frau einen Stein (oder einen Würfelbecher)."],["Blumen zu ihren Füßen","Zu Füßen der Spieler blühen Blumen."],["Gepunztes Leder","Der Lederhintergrund ist mit feinen Punkten gepunzt, die das Licht fangen."],["Rautenbänder","Rautenbänder auf Gold rahmen die Türen oben und unten."]]},"liberale":{"title":"Die Schachspieler","artist":"Liberale da Verona","date":"um 1475","place":"Italien (Verona)","game":"Schach","medium":"Tempera auf Holz","size":"34,9 × 41,3 cm","credit":"Sammlung Maitland F. Griggs, Vermächtnis von Maitland F. Griggs, 1943","p":["Ein Fragment von der Front eines Cassone, der bemalten Truhe, in der eine Braut im Italien der Renaissance ihre Aussteuer aufbewahrte. Liberale war auch für seine Buchmalereien in den Chorbüchern des Doms von Siena bekannt.","Es zeigt einen Augenblick aus einer nicht bestimmten Liebesgeschichte. Auf dem Gegenstück scheint ein Mädchen am Fenster einen jungen Mann hereinzuwinken; hier spielen die beiden Schach. Laut Museum steht sie kurz davor zu verlieren. Schach war in der Liebesdichtung der Zeit ein beliebtes Bild für das Werben."],"spots":[["Das Schachbrett","Ein rot-weißes Brett mit dunklen Figuren; die Partie scheint dem Ende nahe."],["Der junge Mann","Er greift zum Brett und steht wohl vor dem Sieg."],["Das Mädchen","Ihm gegenüber; auf dem Gegenstück winkt sie ihn vom Fenster aus herein."],["Das Fenster","Hinter dem offenen Fenster ein Hügel und der Himmel."],["Zuschauende junge Männer","Männer mit verschränkten Armen verfolgen die Partie."],["Zuschauende junge Frauen","Frauen schauen hinter der Säule dem Spiel zu."]]},"mirror":{"title":"Spiegelkapsel mit Schach spielendem Paar","artist":"Unbekannt","date":"1325–50","place":"Frankreich (Paris)","game":"Schach","medium":"Elfenbein","size":"Durchmesser 10,2 cm","credit":"Erworben aus dem J. H. Wade Fund, 1940","p":["Diese handtellergroße Elfenbeinscheibe war der Deckel eines Handspiegels. Im Paris des 14. Jahrhunderts steckte ein polierter Metallspiegel zwischen zwei Elfenbeinplatten und wurde bei sich getragen; solche Schnitzereien waren Luxusgüter, die Hof und Adel schätzten.","In einem Zelt mit gerafften Vorhängen spielen ein junger Mann und eine Dame Schach. In den Romanen des Mittelalters stand Schach zugleich für Liebe und Krieg. Man hat in dem Paar Tristan und Isolde oder Lancelot und Guinevere sehen wollen, doch niemand weiß es. Das Museum fragt seine Besucher: Wer gewinnt wohl gerade?"],"spots":[["Das Schachbrett","Ein Brett auf einem einbeinigen Tisch, auf dem einige Figuren stehen."],["Der junge Mann","Er greift hinüber, um seinen nächsten Zug zu machen."],["Die Dame","Eine Frau mit Haube; ihre Fingerspitzen berühren eine Figur."],["Die geschlossene Hand","Ihre andere Hand liegt geschlossen im Schoß. Hält sie eine geschlagene Figur?"],["Das Zelt","Beidseitig geraffte Vorhänge – eine beliebte Kulisse für Schachszenen auf Spiegelkapseln."]]},"morris":{"title":"Ein Spielbrett (Mühle)","artist":"Peter Flötner","date":"1500–46","place":"Deutschland","game":"Mühle","medium":"Holzschnitt","credit":"Charles W. Harkness Endowment Fund, 1923","p":["Ein Holzschnitt von Peter Flötner, einem der begabtesten Bildhauer im Nürnberg der Renaissance, der auch Ornamente, Möbel, Goldschmiedemodelle und ein für seine Satire berühmtes Kartenspiel entwarf. Unter dem wirbelnden Rankenwerk verbirgt sich das Brett der Mühle: drei ineinanderliegende Quadrate, die in der Mitte jeder Seite verbunden sind.","Das Brett hat 24 Punkte. Wer drei eigene Steine in eine Reihe bringt (eine Mühle), nimmt dem Gegner einen weg. Solche Drucke dienten Handwerkern auch als Vorlagen; das Museum zeigte dieses Blatt in einer Ausstellung von Goldschmiedemodellen und -entwürfen. Ob man auf dem Papier selbst spielte oder es in Holz oder Metall übertrug, ist nicht überliefert."],"spots":[["Das mittlere Quadrat","Das innerste Quadrat, ganz mit feinem Flechtwerk gefüllt."],["Eine äußere Ecke","Eine Ecke des äußeren Quadrats – einer der 24 Punkte für die Steine."],["Eine mittlere Ecke","Auch die Ecken des mittleren Quadrats sind Punkte."],["Die Verbindungslinien","Bänder verbinden die drei Quadrate in der Mitte jeder Seite; auch auf ihnen ziehen die Steine."],["Eine Maske","Rollwerkkartuschen mit Gesichtern oben, unten und an den Seiten – Groteskenornament der Renaissance."],["Die Weinrankenbordüre","Blätter und Früchte, weiß aus dem schwarzen Grund geschnitten."]]},"leifeng":{"title":"Brettspiel der Leifeng-Pagode","artist":"Unbekannt","date":"1736–95 (Qianlong-Zeit)","place":"China","game":"Wettlaufspiel","medium":"Holzschnitt; Tusche auf Papier","size":"31 × 29,8 cm","credit":"Erworben aus dem J. H. Wade Fund, 2025","p":["Ein zum Spielen gedrucktes Einzelblatt aus der Regierungszeit des Qianlong-Kaisers im China der Qing. Auf seinen Feldern stehen die Figuren der Legende von der Weißen Schlange: der Schlangengeist Bai Suzhen („Weiße Dame“), ihre Gefährtin Xiaoqing („Kleine Grüne“), der junge Xu Xuan (in späteren Fassungen Xu Xian) und der Mönch Fahai, der die Weiße Dame am Ende unter der Leifeng-Pagode am Westsee einschließt.","Die Bahn windet sich von einem Feld mit der Aufschrift 起馬, „los“, spiralförmig zur Pagode in der Mitte. Vermutlich lief man mit Würfeln durch die Geschichte, ähnlich wie beim abendländischen Gänsespiel; die Regeln sind nicht überliefert. Laut Museum wurden solche Farbdrucke in den Städten verkauft und an die Wand gehängt – Teil der städtischen Bildkultur, jede Farbe von einem eigenen geschnittenen Stock gedruckt."],"spots":[["Start","Das Feld mit 起馬, „los“ – vermutlich der Startpunkt."],["Weiße Dame und Kleine Grüne","Der Schlangengeist Bai Suzhen und ihre Gefährtin Xiaoqing."],["Xu Xuan","Der junge Mann, der die Weiße Dame heiratet."],["Der Mönch Fahai","Der Mönch, der sie unter der Pagode einschließt."],["Die Leifeng-Pagode","Die Pagode am Westsee in Hangzhou, wo die Geschichte endet."],["Die Mitte","Eine Frau vor der Pagode und ein kniender Mann – die letzte Szene der Geschichte und vielleicht das Ziel."]]},"tutinama":{"title":"Der verwundete Affe beißt dem Prinzen, seinem Schachpartner, in die Hand (aus einem Tuti-nama, Erzählungen eines Papageis)","artist":"Dasavanta","date":"um 1560","place":"Indien (Mogulhof Akbars)","game":"Schach","medium":"Gouache, Tusche und Gold auf Papier","size":"20 × 14,2 cm (Bild 10,2 × 10,6 cm)","credit":"Schenkung von Mrs. A. Dean Perry, 1962","p":["Eine Illustration aus dem Tuti-nama, den „Erzählungen eines Papageis“, entstanden am Hof des Mogulkaisers Akbar. Es ist eine der Geschichten, mit denen eine Papageienmutter ihre Jungen vor Freundschaften mit anderen Tierarten warnt – etwa mit den Fuchswelpen. Darin spielte ein schachkundiger Affe oft mit einem Prinzen.","Eines Tages machte der Affe vor Gästen einen bösen Scherz; der Prinz ohrfeigte ihn, und der Affe biss ihm in die Hand. Rechts draußen bereiten Diener das Essen, während die Gäste verblüfft zusehen. Eine Inschrift unten nennt Dasavanta, der später zu den berühmtesten Meistern am Mogulhof gehörte; als junger Maler legte er eine kühle blaue Schicht unter sein Bild."],"spots":[["Der Affe","Er beißt dem Prinzen, seinem Schachpartner, in die Hand."],["Der Prinz","Der gebissene Prinz."],["Das Schachbrett","Ein Brett mit roten Feldern auf dem Boden."],["Die verblüfften Gäste","Die geladenen Gäste."],["Das Essen","Draußen setzen Diener Töpfe aufs Feuer."],["Der persische Text","Oben steht die Geschichte auf Persisch."]]},"teniers":{"title":"Die Backgammonpartie","artist":"David Teniers","date":"1640er Jahre","place":"Flandern","game":"Backgammon","medium":"Öl auf Holz, auf Leinwand übertragen","size":"59 × 80,6 cm","credit":"Schenkung von Mr. und Mrs. Samuel D. Wise, 1943","p":["Eine Backgammonpartie um hohe Einsätze, gemalt vom Flamen Teniers. Das Spiel ist sehr alt: Seine heutige Form entstand im 15. Jahrhundert, und der Name „Backgammon“ kam etwa zur Zeit dieses Bildes auf. Im 17. Jahrhundert war es äußerst beliebt und wurde oft um Geld gespielt.","Zuschauer drängen sich um die beiden Spieler, und an der Wand führt jemand Buch. Wegen der zuschauenden Frauen – eine lehnt aus einem Fenster – hält das Museum den Raum für das Spielzimmer eines Bordells. Solche Spielszenen trugen oft eine Moral: Glücksspiel sei töricht, ja verwerflich, und Zeitverschwendung."],"spots":[["Das Brett","Ein aufgeklapptes Backgammonbrett auf dem Tisch, die Partie läuft."],["Der Mann in Weiß","Ein Spieler von hinten, der nach seinen Steinen greift."],["Der Grübler","Sein Gegner, die Wange in die Hand gestützt."],["Der Anschreiber","Ein Mann markiert eine Tafel an der Wand – Punkte oder Einsätze?"],["Die Frau am Fenster","Eine ältere Frau schaut von oben zu."],["Das Hinterzimmer","Hinten trinken Männer neben einer jungen Frau."]]},"imari":{"title":"Schale mit zwei Go-Spielern","artist":"Unbekannt","date":"18. Jahrhundert","place":"Japan (Edo-Zeit)","game":"Go","medium":"Porzellan, geformt, mit Aufglasurfarben (Hizen, Imari-Stil)","size":"2,4 × 13,8 cm","credit":"Severance and Greta Millikin Collection, 1964","p":["Auf dieser kleinen quadratischen Schale spielen zwei Männer unter einer Kiefer Go: der eine in Gelb sitzt vor dem Brett, das direkt auf dem Boden liegt; sein Gegner in Grün lehnt am Baum.","Es ist Imari-Porzellan aus Hizen (heute Saga und Nagasaki); seine Grüntöne erinnern an Kutani-Emails. Gefertigt wurde es für den Export, als Japan China als wichtigsten Porzellanlieferanten Europas abgelöst hatte."],"spots":[["Das Go-Brett","Ein gerastertes Brett, direkt auf dem Boden."],["Der Mann in Gelb","Er sitzt vor dem Brett."],["Der Mann in Grün","Sein Gegner, lächelnd an den Baum gelehnt."],["Die Kiefer","Eine Kiefer breitet ihre Zweige über ihnen aus."],["Der rote Rahmen","Ein roter Rahmen mit abgeschrägten Ecken umgibt die Szene."]]},"shoei":{"title":"Die vier Künste (einer von zwei Stellschirmen)","artist":"Kanō Shōei zugeschrieben","date":"spätes 16.–frühes 17. Jahrhundert","place":"Japan (Momoyama-Zeit)","game":"Go","medium":"Einer von zwei sechsteiligen Stellschirmen; Tusche und leichte Farben auf Papier","size":"153 × 358,6 cm","credit":"John L. Severance Fund, 1979","p":["Ein sechsteiliger Stellschirm, Kanō Shōei aus der Kanō-Schule zugeschrieben. Zusammen mit seinem Gegenstück zeigt er die „vier Künste“, die man von einem gebildeten chinesischen Herrn erwartete: Qin spielen, Qi (Go) spielen, Kalligrafie und Malerei. Hier ruhen vornehme chinesische Herren mit ihren Dienern unter Kiefern auf dem Land.","In der Mitte spielen zwei Männer Go, ein dritter schaut zu. Daneben stehen auf einem Tisch Bücher und eine Qin, noch in ihrer Stoffhülle, die darauf wartet, gespielt zu werden. Die Szene hält Vergnügen und Förmlichkeit im Gleichgewicht. Das Museum weist darauf hin, dass einer der Diener von einem Fisch im Wasser abgelenkt ist."],"spots":[["Das Go-Brett","Ein Brett mit Füßen; zwei Herren spielen einander gegenüber."],["Die Herren","Zwei Spieler und ein dritter, der zuschaut."],["Der Tisch","Wohl der Tisch mit den Büchern und der Qin in ihrer Hülle."],["Die Diener","Diener, die beim Tisch warten."],["Der abgelenkte Diener","Am Wasser liegend, schaut er einem Fisch zu."],["Die Kiefer","Eine große Kiefer breitet ihre Zweige über die Szene."]]},"umaya":{"title":"Stallschirm (Go und Shogi auf der Veranda)","artist":"Unbekannt","date":"Frühes 16. Jahrhundert","place":"Japan (Muromachi-Zeit)","game":"Go und Shogi","medium":"Einer von zwei sechsteiligen Stellschirmen; Tusche, Farben und Gold auf Papier","size":"146,1 × 346,6 cm","credit":"Edward L. Whittemore Fund, 1934","p":["Dieser Stellschirm aus sechs verbundenen Feldern ist einer von einem Paar. Die wertvollen Pferde in ihren Ständen mögen das Hauptthema sein, doch auf der Veranda davor ist viel los.","Dort fordern sich Menschen in zwei Brettspielen heraus: links Go, rechts Shogi. Wie das Museum schreibt, lebt die Szene vom Wechselspiel zwischen den unruhigen Pferden und der stillen Strategie der Spiele. In Japan galten Affen als Beschützer der Pferde und wurden manchmal in Ställen gehalten."],"spots":[["Das Go-Brett","Ein fein liniertes Brett mit schwarzen Steinen."],["Zwei Männer mit schwarzer Kappe","Männer mit hoher schwarzer Eboshi-Kappe: der in Grün greift zum Brett, der in Rot schaut zu."],["Das Shogi-Brett","Große Felder – viel weniger als auf dem Go-Brett."],["Der lachende Gegner","Ein kahlgeschorener Mönch nimmt einen Stein, während der Mann gegenüber sich an den Kopf fasst und laut lacht. Hat gerade jemand gepunktet?"],["Ein Affe","Am Ende der Veranda – ein Affe in rotem Rock?"],["Ein Pferd","Ein schwarzes Pferd bäumt sich auf, von Seilen gehalten."]]},"goryeo":{"title":"Kanne mit eingelegten Go-Spielern","artist":"Unbekannt","date":"13. Jahrhundert","place":"Korea (Goryeo-Dynastie)","game":"Go (Baduk)","medium":"Seladon mit Einlagen aus weißem und schwarzem Schlicker","size":"H. 20,4 cm, Dm. 14,3 cm","credit":"Geschenk von John L. Severance, 1917","p":["Eine Seladonkanne der Goryeo-Zeit mit Tülle und Henkel. Die Einlagetechnik – Linien in den Ton ritzen, mit weißem und schwarzem Schlicker füllen, dann glasieren und brennen – war die Spezialität der Goryeo-Töpfer; hier heben sich in einem runden Medaillon zwei unter einer Weide sitzende Gestalten weiß ab.","Zwischen ihnen liegt ein Brett, und das Museum vergleicht die Szene mit Bildern vom Go-Spiel – auf Koreanisch Baduk. Zither, Go, Kalligrafie und Malerei waren die „vier Künste“ des gebildeten Gelehrten, und ihre eleganten Zusammenkünfte wurden auch zu Motiven des Kunsthandwerks. Koreanisches Seladon mit Menschenfiguren ist selten."],"spots":[["Das Brett","Das Brett zwischen den beiden, ein weißes Quadrat."],["Die Gestalt links","Sitzt dem Brett zugewandt."],["Die Gestalt rechts","Der Gegner, gegenüber sitzend."],["Die Weide","Weidenzweige hängen über ihnen, mit schwarzem Schlicker gezeichnet."],["Der Wolkenrahmen","Wolkenartige Ranken umlaufen das runde Medaillon."],["Das Craquelé","Feine Risse in der Glasur. Sie entstehen beim Abkühlen, weil Ton und Glasur verschieden stark schwinden."]]},"kangra":{"title":"Paar beim Chaupar auf einer Terrasse","artist":"Unbekannt","date":"um 1790–1800","place":"Indien (Pahari, Kangra-Schule)","game":"Chaupar","medium":"Zeichnung mit Vorzeichnung in rotem Ocker","size":"19,4 × 13,2 cm","credit":"Edward L. Whittemore Fund, 1936","p":["Eine Zeichnung eines Künstlers aus Kangra in den Pahari-Bergen am Fuß des Himalaya. Die erste Skizze entstand in Rot (roter Ocker) und wurde dann in Schwarz ausgearbeitet. Da keine Farbe darüberliegt, lässt sich jede Linie der Figuren und Gegenstände verfolgen.","Ein Mann und eine Frau sitzen auf einer Terrasse zu beiden Seiten eines kreuzförmigen Bretts und spielen Chaupar – ein altes indisches Laufspiel auf demselben Kreuz wie Pachisi, bei dem man mit langen Würfeln (Pasa) zieht. Die Felder sind auf dem Brett noch nicht eingezeichnet. Dienerinnen umsorgen das Paar."],"spots":[["Das Kreuzbrett","Ein kreuzförmiges Brett auf dem Boden. Seine Felder sind noch nicht gezeichnet."],["Die Frau","Die Handfläche nach oben – gleich wirft sie die Würfel?"],["Der Mann","Turban mit Federbusch; er greift zum Brett."],["Die Dienerin links","Sie hält ein Fläschchen und reicht ein Tuch."],["Die Dienerin rechts","Sie hält ein langstieliges Gerät und ein kleines Gefäß."],["Die rote Vorzeichnung","Rund um den Turban schimmert die rote Skizze unter den schwarzen Linien hervor."]]},"vuillard":{"title":"Die Damepartie (aus Landschaften und Interieurs)","artist":"Édouard Vuillard","date":"1899","place":"Frankreich","game":"Dame","medium":"Farblithografie (Zustand III/III); gedruckt von Auguste Clot, verlegt von Ambroise Vollard","size":"Bild 33 × 25,7 cm (Blatt 38 × 30,8 cm)","credit":"Geschenk des Hanna Fund, 1951","p":["Ambroise Vollard, Händler impressionistischer Malerei, war auch ein bedeutender Verleger von Druckgrafik. 1895 gab er bei Pierre Bonnard eine Mappe mit 12 Farblithografien in Auftrag; viele weitere folgten, darunter Vuillards Landschaften und Interieurs, gedruckt vom Meisterdrucker Auguste Clot.","Bonnard und Vuillard gehörten zu den Nabis – hebräisch für „Propheten“ –, die eine neue Kunst suchten, in der Form und Farbe selbst Gefühl ausdrücken, und die Szenen aus dem Stadt- und Familienleben liebten. In einem Raum voller Muster sitzen sich zwei Männer am Damebrett gegenüber, eine Frau steht daneben und schaut zu. Auf Französisch heißt das Spiel „dames“; die Bleistiftnotiz unten links lautet „partie de dames“, eine Damepartie."],"spots":[["Das Brett","Ein kleines kariertes Brett mit den aufgestellten Steinen."],["Der Mann links","Ein bärtiger Mann greift über das Brett."],["Der Mann rechts","Sein Gegner, im Sessel über das Brett gebeugt, halb verdeckt von der stehenden Frau."],["Die stehende Frau","Die Hand am Kinn, verfolgt sie die Partie."],["Die Lampe","Eine Lampe an der Wand. Tapete und Polster sind voller Muster."],["Die Bleistiftnotiz","Unten links mit Bleistift: „partie de dames“ – eine Damepartie."]]},"talbot":{"title":"Die Schachspieler (frühe Fotografie)","artist":"William Henry Fox Talbot zugeschrieben","date":"um 1843–47","place":"England","game":"Schach","medium":"Salzpapierabzug","size":"19,9 × 15 cm","credit":"Erworben mit Mitteln von Mr. und Mrs. Everett Kovler","p":["Talbots Negativ-Positiv-Verfahren und die beliebig vielen Abzüge, die es ermöglichte, prägten die Fotografie bis ins digitale Zeitalter. Seine frühen Versuche zeigen wissenschaftliches Interesse wie künstlerischen Anspruch; nachweislich machte er zehn oder mehr Aufnahmen von Schachspielern.","Diese aber stammt vielleicht nicht von ihm: Dieser und andere Abzüge der Szene sind unsigniert und auf anderem Papier als Talbots üblichem. Die Dargestellten sind wohl der Fotograf Antoine Claudet und Talbots Assistent Nicolaas Henneman; neuere Forschung vermutet, dass die Bilder in Claudets Atelier entstanden, an Henneman gingen und zu Talbot kamen, als Henneman ihm Abzüge zur Begleichung einer Schuld gab (Museumstext)."],"spots":[["Das Brett","Das Schachbrett auf dem Tisch, die Figuren aufgereiht."],["Der Mann mit Zylinder","Den Hut noch auf, greift er nach einer Figur."],["Der Grübler","Die Hand am Kinn, studiert der Gegner das Brett."],["Der Vorhang","Ein Vorhang im Hintergrund – eine Kulisse für die Aufnahme?"],["Ein zweiter Hut","Ein weiterer Zylinder liegt rechts auf dem Gestell."]]},"pvl":{"title":"Würfelspielende Männer","artist":"Meister PVL","date":"um 1520","place":"Niederlande","game":"Würfel","medium":"Kupferstich auf Papier","size":"9,4 × 9,4 cm (rund)","credit":"Charles Hack und Hearn Family Trust Collection, erworben 2023","p":["Das Werk eines namentlich unbekannten Stechers, der zu Beginn des 16. Jahrhunderts in den Niederlanden tätig war; nach dem Monogramm „PVL“ unten links heißt er Meister PVL. Auf einem runden Blatt, das in eine Handfläche passt, bauen dichte, feine Linien die Tiefe des Raums und die Stofflichkeit der Kleider auf.","Auf dem Tisch liegen zwei Würfel. Ein vorgebeugter Mann und ein Jüngling mit Pelzkragen zeigen mit dem Finger und streiten – vielleicht um die Augenzahl. Hinten schauen Frauen zu, unter dem Tisch steht ein Weinkrug. Würfel sind seit der Antike mit dem Glücksspiel verbunden und wurden immer wieder verboten."],"spots":[["Die Würfel","Zwei Würfel rollen über den Tisch."],["Zeigende Hände","Zwei Finger treffen sich auf dem Tisch – Streit um die Augenzahl?"],["Der Mann mit breitem Hut","Vorgebeugt; seine geschlitzten Puffärmel waren damals Mode."],["Der Jüngling mit Pelzkragen","Großer Hut und Pelzkragen."],["Die zuschauenden Frauen","Frauen spähen von hinten auf das Spiel."],["Das Monogramm","„PVL“ unten links – der einzige Hinweis auf den Namen des Künstlers."]]},"kiyohiro":{"title":"Sugoroku-Spielerinnen","artist":"Torii Kiyohiro","date":"um 1750","place":"Japan (Edo-Zeit)","game":"Ban-Sugoroku","medium":"Farbholzschnitt (Benizuri-e), Ōban; Verleger Urokogataya","size":"43,5 × 29,3 cm","credit":"Clarence Buckingham Collection","p":["Torii Kiyohiro war ein Ukiyo-e-Künstler, tätig etwa von 1737 bis 1776. Dies ist ein Benizuri-e, gedruckt mit wenigen Farbplatten – Beni-Rosa, Grün und Ähnlichem – in den Jahren, bevor 1765 die vielfarbigen Nishiki-e aufkamen.","Auf dem schwarzen Gestell wird Ban-Sugoroku gespielt: Zwei Spieler würfeln und ziehen weiße und schwarze Steine; wer zuerst alle eigenen hinausgespielt hat, gewinnt. Es gehört zur selben Familie wie Backgammon, und Ukiyo-e-Drucke zeigen oft Frauen bei diesem Spiel. Dahinter raucht eine Frau eine lange Pfeife und sieht zu."],"spots":[["Das Brett","Ein Sugoroku-Brett auf seinem Gestell, mit weißen und schwarzen Steinen."],["Die Gestalt links","Sie greift nach einem Stein."],["Die Frau rechts","Über das Brett gebeugt, studiert die Gegnerin die Steine."],["Die Frau mit der Pfeife","Mit langer Kiseru-Pfeife verfolgt sie das Spiel von hinten."],["Die erhobene Hand","Die Frau rechts hält etwas Kleines, Schwarzes hoch – den Würfelbecher?"],["Die Signatur","„Torii Kiyohiro hitsu“, mit dem Siegel des Verlegers Urokogataya."]]},"ingram":{"title":"Das chinesische Schachspiel","artist":"John Ingram, nach François Boucher","date":"1741–63","place":"Frankreich (Paris)","game":"Xiangqi","medium":"Radierung und Kupferstich","size":"Blatt 39,4 × 27,7 cm (Platte 24,5 × 16,4 cm)","credit":"Elisha Whittelsey Collection, 1966","p":["Eine Zeichnung des französischen Malers François Boucher, gestochen vom gebürtigen Londoner John Ingram. Ingram zog nach Paris und schuf zwischen 1741 und 1763 eine Folge von Stichen nach Bouchers Chinoiserien – China, wie Europäer es sich vorstellten. Der Titel lautet „LE JEU D'ECHETS CHINOIS“, das chinesische Schachspiel.","Eine Frau mit hochgestecktem Haar zieht eine Figur auf dem Brett auf ihrem Schoß, ein kleines Kind schaut zu. Das Spiel gilt als Xiangqi, doch echte Xiangqi-Steine sind alle flache Scheiben, während hier hohe Figuren neben kleinen viereckigen stehen. Auch die Palme und die Figur auf der Urne gehören weniger zu China als zu dem fernen Land, von dem Europa damals träumte."],"spots":[["Brett und Figuren","Das Brett auf ihrem Schoß, mit hohen und viereckigen Figuren. Echte Xiangqi-Steine sind flache Scheiben."],["Die Hand an der Figur","Ihre rechte Hand zieht eine Figur."],["Kinn in der Hand","Die linke Hand am Kinn, blickt sie auf das Brett."],["Das zuschauende Kind","Ein Kind steht am Brett und verfolgt das Spiel."],["Die Figur auf der Urne","Eine Figur sitzt mit gekreuzten Beinen auf einer großen Urne."],["Titel und Namen","„Dessiné par Fr. Boucher“, „Gravé par Ingram“ und der Titel „LE JEU D'ECHETS CHINOIS“."]]},"posada":{"title":"Das Gänsespiel","artist":"José Guadalupe Posada","date":"1909","place":"Mexiko","game":"Gänsespiel","medium":"Hochdruck von Zinkplatte auf Papier","size":"29,3 × 39,4 cm","credit":"William McCallin McKee Memorial Endowment","p":["Ein Spielbogen des mexikanischen Grafikers Posada – berühmt für seine Skelett-Calaveras – für den Verleger Antonio Vanegas Arroyo in Mexiko-Stadt. Das Band unten links lautet „JUEGO DE LA OCA“ (Gänsespiel), und die Bahn windet sich von Feld 1 bis zur 63 in der Mitte.","In der Mitte stehen die Regeln (EXPLICACION): Ein erster Wurf von 5 und 4 führt auf 26, von 6 und 3 auf 53. Wer auf eine Gans (einen Vogel) kommt, zieht dieselbe Zahl noch einmal; im Wirtshaus (Venta, 19) setzt man zwei Würfe aus; im Brunnen (Poso, 31) und im Gefängnis (Carcel, 52) bleibt man, bis ein anderer kommt; das Labyrinth (42) schickt zurück auf 39, der Tod (Muerte, 58) an den Start. Die 63 muss genau getroffen werden. Auf bestimmten Feldern zahlte man Einsätze – es war auch ein Glücksspiel."],"spots":[["Die Regeln","Die „EXPLICACION“ in der Mitte: was jedes Feld bewirkt und wann ein Einsatz fällig ist."],["Feld 1","Der Start. Von hier windet sich die Bahn zur Mitte."],["Der Brunnen (31)","Ein Brunnen wie eine Fontäne. Wer hineinfällt, bleibt, bis ein anderer kommt."],["Der Tod (58)","Das Totenkopffeld: zurück an den Start."],["Das Titelband","„JUEGO DE LA OCA“ auf dem Band unten links, darunter spielende Kinder."],["Der Name des Verlegers","Das Band der Göttin trägt „IMPRENTA DE A. VANEGAS ARROYO“ – der Verlag vieler Drucke Posadas."]]},"jintile":{"title":"Fliese mit Frauen beim Brettspiel","artist":"Unbekannt","date":"13. Jahrhundert","place":"China (Jin-Dynastie)","game":"Brettspiel (wohl Go)","medium":"Irdenware (geformtes Relief)","size":"H. 27,3 cm, B. 24,8 cm, T. 5,4 cm","credit":"Erworben mit Spenden der Friends of Asian Art, 2002","p":["Eine Relieffliese aus der Zeit der Jin (1115–1234), der Dynastie der Dschurdschen, die Nordchina beherrschten. Unter einem blühenden Baum sitzen sich zwei Frauen auf einem Podest gegenüber, ein Brett zwischen sich.","Das Brett zeigt ein feines Gitter – sie spielen wohl Go. Die rechte Frau beugt sich vor und zeigt auf das Brett, die linke schaut zu. Viele Gräber der Jin-Zeit in Nordchina waren mit Reliefziegeln voller Alltagsszenen ausgekleidet, und diese Fliese schmückte vermutlich ein solches Grab."],"spots":[["Das Brett","Ein fein gerastertes Brett, wohl ein Go-Brett."],["Die zeigende Hand","Die rechte Frau zeigt auf das Brett. Ihr nächster Zug?"],["Die Frau links","Mit hochgestecktem Haar blickt sie auf das Brett."],["Die Frau rechts","Über das Brett gebeugt."],["Der blühende Baum","Über ihnen breiten sich die Zweige eines blühenden Baums aus."],["Das Podest","Das Podest, auf dem sie sitzen, mit einer gewellten Zarge zwischen den Beinen."]]},"kyosai":{"title":"Ein Furz wirft eine Go-Partie um (aus einem Skizzenalbum)","artist":"Kawanabe Kyōsai","date":"Mitte bis Ende 19. Jahrhundert","place":"Japan (Edo- bis Meiji-Zeit)","game":"Go","medium":"Eine Doppelseite eines Leporello-Albums mit 26 Doppelblättern; Tusche und Farben auf Papier","size":"Album (geschlossen) 28 × 18 cm","credit":"Geschenk von Anne und Anthony d’Offay zu Ehren von Evan Turner","p":["Eine Szene aus einem Skizzenalbum von Kawanabe Kyōsai (1831–1889), einem Maler vom Ende der Shogunatszeit bis in die Meiji-Ära, mit schnellen, freien Pinselstrichen auf die Seiten eines Faltalbums gesetzt. In der strengen Technik der Kanō-Schule ausgebildet, war Kyōsai auch für Dämonen, Karikaturen und Satiren beliebt.","Der Titel des Museums sagt alles: „Ein Furz wirft eine Go-Partie um“. Links beugt sich ein Mann mit schwarzer Kappe vor; rechts fliegt das Brett durch die Luft, die Steindosen lassen Steine regnen, und der Gegner fällt rücklings um. Eine ernste Partie, mit einem Knall ruiniert – Kyōsai hält mit flinkem Pinsel den alten japanischen Furzhumor fest, den schon mittelalterliche Bildrollen kennen."],"spots":[["Der Mann mit schwarzer Kappe","Vorgebeugt, das Hinterteil herausgestreckt – der Verursacher?"],["Das fliegende Brett","Das linierte Go-Brett fliegt schräg davon."],["Dosen und Steine","Zwei Steindosen kippen, die Steine prasseln herab."],["Der Fächer","Ein offener Fächer fliegt neben dem Brett davon."],["Der umgeworfene Gegner","Auf dem Rücken, mit weit aufgerissenen Augen."],["Die Pinselführung","Kräftige Tuschelinien, wie in einem Zug ohne Vorzeichnung."]]},"yokuts":{"title":"Spieltablett für Glücksspiele","artist":"Yokuts-Flechterin (Name unbekannt)","date":"um 1900","place":"USA (bei Dunlap, Kalifornien)","game":"Huuchuish (Walnussschalen-Würfel)","medium":"Pflanzenfasern (Spiralwulsttechnik)","size":"H. 5,1 cm, Dm. 61 cm","credit":"Erworben mit Mitteln von Mrs. Leonard S. Florsheim Jr.","p":["Viele indigene Völker Kaliforniens spielten Glücksspiele. Dieses Tablett diente dem Huuchuish, einem Würfelspiel nur für Frauen: Acht Würfel aus Walnussschalen wurden auf das Tablett geworfen, gezählt wurde mit Stäbchen.","Das in das Tablett eingeflochtene Rundmuster zeigt das Spiel selbst – die Würfel, die Zählstäbchen und die Spielerinnen (Museumstext). Ein Spielgerät, das das Bild seines eigenen Spiels trägt. Auf dem Foto liegen Walnusswürfel auf und neben dem Tablett."],"spots":[["Die Spielerinnen","Figuren umrunden den Rand – die Teilnehmerinnen."],["Zählstäbchen","Bündel kurzer senkrechter Striche: die Stäbchen zum Zählen."],["Runde Motive","Kleine runde Motive – vielleicht die Würfel?"],["Ein Walnusswürfel","Ein Würfel aus Walnussschale. Acht davon wurden geworfen."],["Das Dreiecksband","Ein Band dunkler Dreiecke läuft rundherum."],["Die Mitte","Die Wulst windet sich aus der Mitte, umgeben von einem gestrichelten Ring."]]},"hokkei":{"title":"Ushiwakamaru besiegt Benkei beim Sugoroku","artist":"Totoya Hokkei","date":"um 1825","place":"Japan (Edo-Zeit)","game":"Ban-Sugoroku","medium":"Surimono (Farbholzschnitt, Shikishiban)","size":"21,8 × 19,1 cm","credit":"Geschenk von Helen C. Gunsaulus","p":["Ein Surimono von Totoya Hokkei (1780–1850), einem Schüler Hokusais. Surimono waren privat in Auftrag gegebene Drucke – oft von Dichterkreisen, mit eigenen Versen – und aufwendiger gefertigt als kommerzielle Ukiyo-e, mit feinem Papier und Metallpigmenten.","Ushiwakamaru, der Kindername des Helden Minamoto no Yoshitsune, und der riesige Kriegermönch Benkei. Berühmt ist ihr Duell auf der Gojō-Brücke in Kyoto, doch hier wird der Kampf zur Sugoroku-Partie: Der Junge sitzt gelassen hinter dem Brett, Benkei mit der Hellebarde auf dem Rücken kratzt sich geschlagen am Kopf – wohl eine spielerische Umdeutung."],"spots":[["Das Sugoroku-Brett","Ein kastenförmiges Brett mit weißen und schwarzen Steinen."],["Benkei kratzt sich am Kopf","In voller Rüstung kratzt sich der Besiegte am Kopf."],["Ushiwakamaru","Der junge Held, hinter dem Brett sitzend."],["Die Hellebarde","Die Klinge von Benkeis großer Naginata."],["Das Gedicht","Verse oben rechts – wohl von dem Kreis, der den Druck bestellte."],["Die Signatur","Hokkeis Signatur in der Kartusche unten rechts."]]},"vorsterman":{"title":"Tricktrackspieler (Nachtszene)","artist":"Lucas Emil Vorsterman, nach Adam de Coster","date":"um 1630","place":"Flandern (Antwerpen)","game":"Backgammon","medium":"Kupferstich auf elfenbeinfarbenem Papier","size":"Bild 25,5 × 34,4 cm","credit":"Bernard F. Rogers Collection","p":["Adam de Coster war um 1630 in Antwerpen ein führender Maler kerzenbeleuchteter Nachtszenen, als Vorsterman in derselben Stadt Werke beliebter Zeitgenossen stach. Der Rubens-Schüler überwarf sich mit seinem Meister und ging nach England; danach schuf er kräftigere, stilisierte, caravaggeske Stiche wie diesen.","Um einen Tisch in einem dunklen Raum beugen sich Männer über ein Tricktrackbrett. Nach De Costers Lichtführung erhellen zwei Kerzenflammen die Gesichter am Tisch (Museumstext). Rechts blickt ein junger Lautenspieler zu uns heraus."],"spots":[["Das Brett","Ein wie ein Kasten aufgeklapptes Brett auf dem Tisch."],["Die Kerze","Eine Kerze im Leuchter; ihre Flamme erhellt die Gesichter."],["Der Mann mit Pfeife","Mit breitem Hut raucht er und schaut zu."],["Der Mann von hinten","Vorgebeugt, die Hände auf dem Tisch."],["Der Lautenspieler","Ein Jüngling mit Laute, der uns anlächelt."],["Die Namen","„A. De Coster pi.“ unten links, „Vorsterman“ unten rechts."]]},"zorn":{"title":"Schachspieler","artist":"Anders Zorn","date":"1891","place":"Schweden","game":"Schach","medium":"Radierung auf elfenbeinfarbenem Büttenpapier","size":"Bild 13,5 × 9,6 cm (Platte 13,9 × 10 cm)","credit":"Wallace L. DeWolf und Charles Deering Collections of Etchings by Anders Zorn","p":["Eine Radierung des schwedischen Künstlers Anders Zorn (1860–1920), der mit Porträts in Öl und Aquarell international berühmt wurde und auch ein großes radiertes Werk schuf. Die Platte ist nicht größer als eine Hand.","Schnelle, schräge, übereinandergelegte Linien genügen, um einen dunklen Raum und zwei Menschen aus dem Kupfer zu holen. Der Mann vorn, mit dem Rücken zu uns, beugt sich über das Brett; die Gestalt gegenüber blickt nach unten und überlegt den nächsten Zug. Die Figuren sind mit feinen Strichen gezeichnet. Wer Modell saß, ist nicht überliefert."],"spots":[["Brett und Figuren","Die helle Fläche unten ist das Brett; die kurzen senkrechten Striche sind Figuren."],["Der Mann vorn","Mit dem Rücken zu uns, über das Brett gebeugt."],["Der Gegner","Mit gesenktem Kopf, den Blick auf dem Brett."],["Der dunkle Hintergrund","Die Tiefe des Raums aus senkrechten Linien."],["Schräge Linien","Der Mantel besteht aus schnellen, übereinandergelegten Diagonalstrichen."],["Die Signatur","Unter der Platte mit Bleistift signiert: „Zorn“."]]},"harunobu-sugoroku":{"title":"Dem Spiel zusehen (Sugoroku)","artist":"Suzuki Harunobu","date":"um 1766","place":"Japan (Edo-Zeit)","game":"Ban-Sugoroku","medium":"Farbholzschnitt (Chūban, Surimono)","size":"28,5 × 21 cm","credit":"Clarence Buckingham Collection","p":["Suzuki Harunobu (1725?–1770) war die zentrale Gestalt, als um 1765 die vielfarbigen Nishiki-e entstanden, von vielen Platten gedruckt. Dies ist ein privat herausgegebenes Surimono, und die weichen, geschichteten Farben zeigen das Neue.","In einem Raum mit blühenden Pflaumen spielen zwei junge Frauen an einem kastenförmigen Sugoroku-Brett, eine dritte steht und schaut zu. Weiße und schwarze Steine füllen das Brett; die Linke zieht einen Stein, die Rechte greift zum Brett. Die Schiebetür dahinter ist mit Wasserfall und Kiefern bemalt."],"spots":[["Das Sugoroku-Brett","Ein kastenförmiges Ban-Sugoroku-Brett mit weißen und schwarzen Steinen."],["Die junge Frau links","Im Kimono mit Papierkranichen zieht sie einen Stein."],["Die junge Frau rechts","Vorgebeugt greift sie zum Brett."],["Die Zuschauerin","Stehend schaut sie zu, einen langstieligen Gegenstand in der Hand."],["Die Pflaume","Eine weiße Pflaume streckt ihre Zweige von oben herein."],["Die bemalte Tür","Eine Schiebetür mit Wasserfall und Kiefern."]]},"kota":{"title":"Maharao Kishor Singh II. von Kota verehrt Krishna als Brij Rajji","artist":"Unbekannt","date":"um 1825","place":"Indien (Rajasthan, Kota)","game":"Pachisi","medium":"Gummi-Tempera, Silber und Gold auf Papier","size":"24,5 × 18,8 cm","credit":"James Albert and Mary Gardiner Ford Memorial Fund","p":["Der Herrscher des kleinen Fürstenstaats Kota (reg. 1819–28), gekleidet als Priester der Pushti-Marg-Sekte, bringt eine Lampe mit fünf Flammen dar. Im kleinen Schrein auf dem Altar stehen Metallbilder Krishnas mit zwei Gefährtinnen – ein Kultbild, das nur in Kota verehrt wird.","Zahlreiche Glaslampen hängen von der Decke, und auf den Stufen zum Altar liegen Spielsachen und Spiele zur Unterhaltung Krishnas und seiner Gefährten: Messingelefanten, Silberkühe, Bälle und ein Pachisi-Brett (Museumstext). Das rote kreuzförmige Tuch ist dieses Brett – Pachisi als Spielzeug des Gottes dargebracht."],"spots":[["Das Pachisi-Brett","Das rote kreuzförmige Tuch auf den Stufen: ein Pachisi-Brett."],["Elefanten","Zwei Messingelefanten neben dem Brett."],["Bälle","Goldene Bälle auf der Stufe darüber."],["Krishna","Die Bilder Krishnas und zweier Gefährtinnen im Schrein."],["Der Herrscher und die Lampe","Als Priester gekleidet, bringt er eine Lampe mit fünf Flammen dar."],["Glaslampen","Eine Fülle von Glaslampen hängt von der Decke."]]},"coyote":{"title":"Das Kojotenspiel","artist":"Nachfolger von José Guadalupe Posada","date":"Undatiert","place":"Mexiko","game":"Kojote und Hennen (Familie von Fuchs und Gänse)","medium":"Hochdruck von Zinkplatte auf Papier","size":"38,2 × 30,5 cm","credit":"William McCallin McKee Memorial Endowment","p":["Ein Spielbogen im Zinkhochdruck, wie Posada sie für die Volksdruckereien von Mexiko-Stadt schuf. Oben steht „JUEGO DEL COYOTE“ (Kojotenspiel); ringsum überfallen Kojoten den Hühnerstall, und ein Mann schwingt einen Stock, um einen zu vertreiben. Der Streifen unten lautet „Eigentum von Ildefonso T. Orellana“.","Die Regeln stehen in der „EXPLICACION“ unten: zwei Spieler, einer mit fünfzehn Hennen, der andere mit einem einzigen Kojoten. Die Hennen ziehen vorwärts oder seitwärts, nie zurück; der Kojote zieht in alle Richtungen und frisst eine Henne, indem er sie überspringt, wenn der Punkt dahinter frei ist. Die Hennen gewinnen, wenn sie den Kojoten einsperren. Es ist dasselbe Jagdspiel wie das europäische Fuchs und Gänse."],"spots":[["Der Platz des Kojoten","Der Kojotenkopf im mittleren Kreis: Hier beginnt der Kojote."],["Die Plätze der Hennen","Kreise mit Hennen: Hier werden ihre Steine aufgestellt."],["Die Regeln","Die „EXPLICACION“: Steine, Züge und Sieg."],["Der Titel","„JUEGO DEL COYOTE“ – das Kojotenspiel."],["Ein Kojote auf Hennenjagd","Unten links geht ein Kojote auf eine Henne los."],["Der Mann mit dem Stock","Oben rechts hebt ein Mann den Stock gegen einen Kojoten."]]},"mons":{"title":"Tricktrack um Mons (Bergen), 1709","artist":"Pieter Nolpe (Platte und Verleger)","date":"Platte 1623–53; Druck um 1709","place":"Niederlande (Amsterdam)","game":"Tricktrack (aus der Backgammon-Familie)","medium":"Radierung, Kupferstich und Vers in Buchdruck","size":"Blatt 35,8 × 18,6 cm (Platte 12,9 × 17,5 cm)","credit":"","p":["Vier Männer spielen am Tisch Tricktrack. Laut dem Museumsdatensatz bezeichnen die Buchstaben A–D den Herzog von Marlborough, den Kurfürsten von Bayern, den Herrn von Ouwerkerk und den Herzog von Villeroy. Das Blatt verspottet die Belagerung und Einnahme von Mons (niederländisch Bergen) durch die Alliierten gegen die Franzosen 1709 als Brettspiel um die Stadt. Im hinteren Raum (E) ist König Philipp V. von Spanien mit einer Frau.","Die Platte ist von Pieter Nolpe als Stecher und Verleger signiert, doch Nolpe starb Anfang der 1650er-Jahre – wahrscheinlich wurde eine alte Platte des 17. Jahrhunderts mit Buchstaben und einem neuen Vers erneut gedruckt. Der Vers beginnt damit, das Spiel der hohen Herren sei nichts als Tiktak und Verkeer (zwei Brettspiele dieser Familie), und verspottet dann jeden Spieler."],"spots":[["Das Brett","Das Tricktrackbrett auf dem Tisch: Es geht um eine Stadt."],["A, Marlborough","Stehend blickt er auf das Brett: der englische Feldherr der Alliierten."],["B, der Kurfürst von Bayern","Barhäuptig, tief im Stuhl."],["C, Ouwerkerk","Mit Federhut: der niederländische General."],["E, der hintere Raum","Hinten im Schlafzimmer Philipp V. mit einer Frau."],["Der Vers","Niederländischer Vers darunter, der die Spieler A bis E verspottet."]]},"stembus":{"title":"Die Wahlurne: ein politisches Gänsespiel","artist":"Johan Michaël Schmidt Crans (Grafiker)","date":"1867","place":"Niederlande","game":"Gänsespiel (Satire)","medium":"Lithografie","size":"66 × 50 cm","credit":"","p":["Ein satirisches Blatt in Form eines Gänsespiels, beigelegt der Wochenschrift De Nederlandsche Spectator, Nr. 9, 2. März 1867, zusammen mit einem losen Regelblatt (Museumsdatensatz). Auf den Feldern erscheinen Porträts der damaligen Minister.","Start ist der Binnenhof, das Parlament in Den Haag; Ziel ist in der Mitte Feld 64, „Insulinde“ – ein poetischer Name für Niederländisch-Indien –, wo ein gemaltes Porträt des Ministers Pieter Mijer an der Insel Java hängt. Mijer war vom Kolonialminister zum Generalgouverneur Indiens geworden, und die Ernennung löste einen politischen Sturm aus. Das zusätzliche Feld, eines mehr als die üblichen 63, ist wohl der Pointe geschuldet."],"spots":[["Der Start","Das Gebäude oben links: Es beginnt am Binnenhof in Den Haag."],["Mijers Porträt","Feld 63: ein gerahmtes Porträt Pieter Mijers, an Seilen von der Insel hängend."],["Insulinde 64","Die Insel und die Zahl 64 in der Mitte: das Ziel."],["Die Wahlurne","„DE STEMBUS“ (die Wahlurne) unten rechts: die Kiste des Titels."],["Die Minister","Aus den Feldern blicken die Gesichter der damaligen Minister."],["Der Hahn","Ein Hahn in einem Feld; worauf er anspielt, ist unbekannt."]]},"koorai":{"title":"Koreaner beim Brettspiel (aus Siebolds Nippon)","artist":"James Erxleben (Lithograf), nach einem Entwurf von „Toioske“","date":"1832–52","place":"Niederlande (Leiden) / Menschen aus Korea","game":"Brettspiel (wohl Go)","medium":"Tonlithografie, handkoloriert","size":"Blatt 38 × 55,5 cm","credit":"Geschenk von F. G. Waller","p":["Eine Tafel aus NIPPON, dem großen Werk, das der in Deutschland geborene Arzt Philipp Franz von Siebold in Leiden nach seinen Eindrücken in der niederländischen Faktorei in Nagasaki (1823–30) veröffentlichte. Oben rechts steht „TAB. I“, unten „KOORAI“ (Korea), dazu niederländisch und deutsch „eine Fischerfamilie“. Erxleben zeichnete sie auf den Stein; als Entwerfer nennt die Tafel „Toioske“.","Vier Männer sitzen auf dem Boden um ein Brett; links führt eine Frau ein kleines Kind an der Hand, rechts steht ein Mann mit langem Stock und Beutel. Vorn liegt ein breitkrempiger schwarzer Hut (Gat). Das Brett zeigt ein Gitter und runde Steine – wohl Go (koreanisch Baduk), auch wenn der Datensatz nur „ein Brettspiel“ nennt."],"spots":[["Das Brett","Gitter mit runden Steinen: wohl eine Partie Go."],["Der schwarze Hut","Ein breitkrempiger schwarzer Hut (Gat) am Boden."],["Mutter und Kind","Eine Frau mit einem Kind an der Hand sieht zu."],["Der stehende Mann","Stehend, mit langem Stock und Beutel."],["Der vorgebeugte Mann","In blauer Jacke späht er auf das Brett."],["Der Titel","„KOORAI“ (Korea), dazu „eine Fischerfamilie“ auf Niederländisch und Deutsch."]]},"cairo":{"title":"Menschen um ein Brettspiel vor einem Café (Kairo)","artist":"Délié & Béchard (Hippolyte Délié und Émile Béchard)","date":"um 1869–90","place":"Ägypten (Kairo)","game":"Brettspiel (wohl Schach)","medium":"Albuminabzug","size":"10,8 × 16,4 cm","credit":"","p":["Eine Fotografie von Hippolyte Délié und Émile Béchard, französischen Fotografen mit Atelier in Kairo. Auf dem Karton stehen der Name des Ateliers, „beim Esbekiya-Garten“, und „Kairo (Ägypten)“. Reisende kauften solche Bilder als Andenken an Ägypten.","Vor einem Laden mit Gitterfenster sitzen Männer auf dem Boden um ein Brett auf einem niedrigen Gestell. Hohe Figuren stehen darauf – wohl Schach (arabisch Schatrandsch), auch wenn der Museumsdatensatz nur „ein Brettspiel“ nennt. Für die lange Belichtung halten alle still."],"spots":[["Brett und Figuren","Das Brett auf einem niedrigen Gestell, mit hohen Figuren: wohl Schach."],["Das Gitterfenster","Ein Fenster mit Holzgitter, typisch für alte Kairoer Häuser."],["Der Mann mit Stock","Sitzend, mit Stock, schaut er zu."],["Der Korb","Ein geflochtener Korb am Boden."],["Das zuschauende Kind","Ein Kind späht von hinten auf das Brett."],["Der Ateliername","„AU JARDIN DE L’ESBÉKIEH“ und „CAIRE (EGYPTE)“ auf dem Karton."]]},"vanmour":{"title":"Armenische Gesellschaft beim Kartenspiel","artist":"Jean-Baptiste Vanmour","date":"um 1720–37","place":"Osmanisches Reich (Istanbul)","game":"Kartenspiel","medium":"Öl auf Leinwand","size":"44,5 × 58,5 cm","credit":"","p":["Der in Flandern geborene Vanmour kam 1699 mit dem französischen Gesandten nach Istanbul und lebte bis zu seinem Tod in der Stadt; er malte Hofzeremonien und den Alltag ihrer Bewohner. Laut Museum zeigt die Kleidung der Männer, dass sie Armenier sind.","Im Licht einer großen Kerze spielen Männer und Frauen an einem rot gedeckten Tisch Karten. Ausgeteilte Karten liegen auf dem Tisch, manche betrachten ihr Blatt. In der linken Ecke spinnt eine alte Frau. Welches Spiel es ist, sagt der Datensatz nicht."],"spots":[["Karten auf dem Tisch","Karten auf dem rot gedeckten Tisch."],["Die große Kerze","Eine einzige Kerze erhellt die Runde."],["Die spinnende Alte","Eine alte Frau spinnt in der linken Ecke."],["Frau mit ihrem Blatt","Ganz rechts betrachtet eine Frau ihre Karten."],["Der Mann im Pelz","Ein Mann im pelzbesetzten Mantel; die Kleidung weist die Männer als Armenier aus."],["Über den Tisch gebeugt","Jemand beugt sich mit Karten in der Hand über den Tisch."]]},"algiers":{"title":"Drei Männer beim Brettspiel (Algier)","artist":"Anonym","date":"1851–1900","place":"Algerien (Algier)","game":"Brettspiel (wohl Backgammon)","medium":"Albuminabzug","size":"14,0 × 10,0 cm","credit":"","p":["Eine anonyme Fotografie, unter dem Bild handschriftlich mit „Alger“ (Algier) beschriftet. Mit Stühlen und einem Tischchen vor schlichtem Hintergrund entstand sie wohl im Atelier. Solche Bilder von Menschen Nordafrikas kauften Reisende und Sammler.","Zwei Männer sitzen einander an einem Brett mit Rand gegenüber; der rechte greift gerade nach einem Stein. Runde Steine sind darauf gestapelt – wohl Backgammon (in der Region u. a. Tawla genannt), auch wenn der Datensatz nur „ein Brettspiel“ nennt. Auf dem Tischchen vorn steht Kaffeegeschirr."],"spots":[["Brett und Steine","Ein Brett mit Rand, darauf gestapelte runde Steine."],["Der stehende Zuschauer","Ein Mann mit Leibbinde steht hinten und schaut aufs Spiel."],["Der Alte links","Ein älterer Mann mit Kopftuch, in Gedanken."],["Der Mann rechts","Mit weißem Tuch über dem Kopf beugt er sich übers Brett."],["Das Kaffeegeschirr","Tablett und Tässchen auf einem durchbrochenen Tischchen."],["Die ziehende Hand","Die Hand des rechten Spielers, gleich greift sie einen Stein."]]},"circo":{"title":"Zirkusspiel (Juego del Circo)","artist":"Manuel Manilla (?)","date":"Undatiert","place":"Mexiko","game":"Glücksspiel mit zwei Würfeln","medium":"Hochdruck (Holzstich oder Autotypie) auf hellbraunem Velinpapier","size":"26,2 × 35,0 cm","credit":"","p":["Ein Spielbogen, mit Fragezeichen dem mexikanischen Grafiker Manuel Manilla zugeschrieben. Unten rechts steht sein Verkäufer, die Druckerei „El Teatro“, mit Adresse. Solche billigen Blätter wurden auf der Straße verkauft und offenbar so, wie sie waren, bespielt.","In der Mitte ein Zirkuszelt, ringsum Kunstreiter, ein Menschenturm, ein Kraftmensch und mehr, jedes Bild mit einer Zahl von 2 bis 12. Die „Esplicacion“ oben links sagt: Alle, auch Kinder, dürfen mitspielen; man wirft zwei Würfel und setzt auf das passende Feld oder nimmt den Einsatz, der dort liegt. Wer zwölf wirft, gewinnt alles."],"spots":[["Das Zirkuszelt","Der Titel „JUEGO DEL CIRCO“ und das Zelt, Feld 12."],["Die Spielregel","Die Regel unter der Überschrift „ESPLICACION“."],["Die Kunstreiterin","Eine Tänzerin auf einem galoppierenden Pferd: Feld 6."],["Der Menschenturm","Ein Mann auf den Schultern eines anderen: Feld 4."],["Der Kraftmensch","Ein Mann stemmt ein kanonenförmiges Gewicht: Feld 8."],["Der Name der Druckerei","„De venta, Estampería ‚El Teatro‘“ und die Adresse."]]},"loteria":{"title":"Lotería-Bilderbogen","artist":"José Guadalupe Posada","date":"1880–1913","place":"Mexiko","game":"Lotería (Bilder-Ausrufspiel)","medium":"Hochdruck (Holzstich oder Autotypie) auf hellbraunem Velinpapier","size":"30,0 × 40,0 cm","credit":"","p":["Der mexikanische Grafiker Posada zeichnete unzählige Bilder für den Verleger Antonio Vanegas Arroyo in Mexiko-Stadt, dessen billige Blätter Nachrichten, Lieder und Spiele verbreiteten. Dieses trägt den Titel „JUEGO DE LOTERIA“ und Vanegas Arroyos Namen.","Achtunddreißig kleine beschriftete Bilder füllen den Bogen: Stern, Mond, Skorpion, Teufel, Totenkopf, Hahn, Druckerei und mehr. Bei der Lotería, ähnlich wie Bingo, zieht ein Ausrufer Karten und nennt die Bilder; wer sie auf seiner Tafel hat, markiert sie mit Bohnen oder Ähnlichem. Der Bogen wurde wohl zu Karten zerschnitten."],"spots":[["Titel und Verlag","„JUEGO DE LOTERIA“ und der Name von Vanegas Arroyos Haus."],["Der Stern","„ESTRELLA“, das erste Bild oben links."],["Der Mond","„LUNA“, eine Sichel mit Gesicht."],["Der Tod","„MUERTE“: ein Skelett mit Sense, das Flöte spielt."],["Der Tlachiquero","„TLACHIQUERO“: ein Mann, der Agavensaft sammelt."],["Die Druckerei","„IMPRENTA“: Arbeiter an der Presse, wo solche Blätter entstanden."]]},"jeupol":{"title":"„Jeu polonais“ oder Damebrett","artist":"Anonym","date":"1833–1900","place":"Belgien oder Niederlande","game":"Dame (10 × 10-Brett)","medium":"Holzschnitt mit Text im Buchdruck","size":"32,2 × 39,6 cm","credit":"","p":["Ein Einblattdruck mit französisch-niederländischem Titel „JEU POLONAIS OF DAMSPEL“. „Jeu polonais“ (das polnische Spiel) hieß in Frankreich die Dame auf dem 10 × 10-Brett. Oben rechts steht die Verlagsnummer „n. 106“.","Wie der Museumsdatensatz sagt, gibt es 100 Felder, 50 weiße und 50 schwarze, mit Zierleisten links und rechts. Steine sind nicht gedruckt – wohl ein billiges Brett, auf dem man so spielte, mit Bohnen oder Knöpfen. Das Papier zeigt noch die Falten."],"spots":[["Der Titel","Die Worte „JEU POLONAIS OF DAMSPEL“."],["Die Nummer","Die Verlagsnummer „n. 106“."],["Die linke Leiste","Eine Reihe runder Blütenmotive."],["Die rechte Leiste","Dasselbe Muster auf der anderen Seite."],["Die hundert Felder","Das 10 × 10-Brett; die dunklen Felder sind schraffiert."],["Die Falte","Eine Falte im Papier; vielleicht trug man es gefaltet bei sich."]]},"dkaart":{"title":"Domino- und Kartenbogen zum Ausschneiden","artist":"Anonym (Brepols)","date":"1800–1833","place":"Belgien (Turnhout)","game":"Domino und Karten","medium":"Holzschnitt, blau, rot und gelb koloriert; Text im Buchdruck","size":"34,3 × 41,9 cm","credit":"","p":["Laut Museumsdatensatz zeigt der Bogen 32 Spielkarten und 28 Dominosteine zum Ausschneiden. Er ist Nummer 114 im Verlagsverzeichnis von Brepols, unten steht der Händler „D. Pouwels, Bergen-op-Zoom“. Der Titel ist niederländisch und französisch.","Links stapeln sich die 28 Steine von Doppel-Leer bis Doppel-Sechs zu einem Dreieck. Rechts stehen 32 Karten, Sieben bis Zehn sowie Bilder und Asse jeder Farbe: ein Blatt für Spiele wie Piquet. Da ihn niemand zerschnitt, sehen wir ihn, wie er aus der Presse kam."],"spots":[["Der Titel","Die Worte „DOMINO EN KAARTSPEL“."],["Doppel-Leer","Die Spitze des Dreiecks: der Stein ohne Augen."],["Doppel-Sechs","Der höchste Stein, rechts in der untersten Reihe."],["Pik-Ass","Die zweite Karte in der linken Spalte."],["Eine Bildkarte","Ein König, rot, blau und gelb koloriert."],["Der Händler","„D. POUWELS, Bergen-op-Zoom“ unten."]]},"apen":{"title":"Zwei Affen beim Tricktrack","artist":"Quirin Boel nach David Teniers","date":"1635–1690","place":"Flandern","game":"Tricktrack (verwandt mit Backgammon)","medium":"Radierung","size":"11,0 × 14,5 cm","credit":"","p":["Blatt einer Folge aus Titel und sechs Blättern, in der Affen menschliche Tätigkeiten nachspielen. Unten links steht „D. Teniers erfand und verlegte, mit Privileg“: Quirin Boel radierte den Entwurf des flämischen Malers Teniers.","Wie der Museumsdatensatz beschreibt, sitzen zwei Affen am Boden, ein Tricktrackbrett zwischen sich. Der linke trinkt Wein aus einem Glas, der rechte mit Hahnenfeder am Hut greift nach einem Stein. Vermutlich ein Spott auf Menschen, die dem Trunk und dem Spiel verfallen sind."],"spots":[["Das Brett","Ein klappbares Tricktrackbrett am Boden, mit Zungen und Steinen."],["Der linke Affe","Ein Affe im Rock vor dem Brett."],["Das Weinglas","Das Glas, das der linke Affe hebt."],["Der Federhut","Eine Hahnenfeder am Hut des rechten Affen."],["Der Krug","Ein Krug zu Füßen des linken Affen."],["Die Inschrift","„D Teniers in et excud cum privilegio“."]]},"dstereo":{"title":"Männer beim Dominospiel am Tisch (Stereofoto)","artist":"Anonym","date":"1850–1880","place":"Unbekannt (niederländische Aufschrift)","game":"Domino","medium":"Albuminabzug (Stereofotografie)","size":"8,5 × 17,0 cm","credit":"","p":["Eine Stereofotografie: zwei fast gleiche Aufnahmen nebeneinander. Im Stereoskop betrachtet, verschmelzen sie zu einem räumlichen Bild. Am linken Rand steht handschriftlich „Het dominospel“ (das Dominospiel).","Vor einem Gebäude steht ein Tisch in der Sonne, Männer in Hemdsärmeln halten ihre Steine. Zwei schauen stehend zu; der rechte Spieler trägt eine weiße Mütze. Da alle stillhalten mussten, wurde die Szene wohl für die Kamera gestellt."],"spots":[["Die Steine","Verdeckt gehaltene Dominosteine."],["Der Mann mit weißer Mütze","Rechts sitzend, mit seinen Steinen."],["Der Mann mit Halstuch","Stehend, er schaut aufs Spiel."],["Der Mann links","Ein junger Mann, auf den Ellbogen gestützt."],["Die Aufschrift","„Het dominospel.“ am linken Rand."],["Das zweite Bild","Das rechte Foto, von leicht versetztem Punkt aus: zusammen wirken beide räumlich."]]},"gojo":{"title":"Zwei Frauen beim Go","artist":"Anonym","date":"1870–1891","place":"Japan","game":"Wohl Go","medium":"Handkolorierter Albuminabzug","size":"9,0 × 13,5 cm","credit":"","p":["Eine Schwarz-Weiß-Fotografie, mit dem Pinsel von Hand koloriert. Solche Bilder entstanden in Ateliers in Yokohama und anderswo als Andenken für Ausländer. Dieses klebte in einem Album mit Fotos einer Reise nach Manila.","Vor einer Nischen-Dekoration und einem Wandschirm sitzen zwei Frauen an einem Brett mit Füßen; die linke setzt einen Stein. Weiße und schwarze Steine liegen darauf – wohl Go, auch wenn der Museumsdatensatz „ein Brettspiel“ sagt. Auf dem Tablett vorn stehen Süßigkeiten und Schalen."],"spots":[["Brett und Steine","Ein dickes Brett mit Füßen, weiße und schwarze Steine."],["Die setzende Hand","Die linke Frau setzt einen Stein."],["Die Frau links","Sie wendet sich uns zu; ihr Obi ist groß gebunden."],["Die Frau rechts","Im gestreiften Kimono, die Hand am Brett."],["Tablett und Schalen","Süßigkeiten und Becher vorn."],["Die Blumen","Eine Blumenvase auf einem Ständer dahinter."]]},"meade":{"title":"Zwei Männer beim Schach","artist":"Charles Richard Meade und Henry William Mathew Meade","date":"1852","place":"Vereinigte Staaten","game":"Schach","medium":"Daguerreotypie","size":"6,9 × 8,3 cm","credit":"","p":["Eine Daguerreotypie aus dem Atelier der Brüder Meade, in England geborene Fotografen, die in Amerika arbeiteten. Die Daguerreotypie entsteht direkt auf einer versilberten Kupferplatte und ist daher ein nicht vervielfältigbares Unikat; diese liegt hinter einem vergoldeten Passepartout in einem kleinen Lederetui.","Zwei junge Männer sitzen an einem Schachbrett auf einem Tischchen; der linke hat die Finger an einer Figur. Der rechte, die Hand auf der Brust, betrachtet die Stellung. Da sie lange stillhalten mussten, ist der Zug wohl gestellt."],"spots":[["Das Schachbrett","Brett und weiße Figuren auf einem mit Blumenstoff bedeckten Tischchen."],["Der Mann links","Die Finger an einer Figur."],["Der Mann rechts","Er blickt aufs Brett."],["Die Hand auf der Brust","Die nachdenkliche Hand des rechten Spielers."],["Das Tuch","Ein kleines Tischchen mit geblümtem Stoff."],["Das goldene Passepartout","Rahmen und Etui, die die Platte schützen."]]},"weiqidai":{"title":"Landschaft mit daoistischen Unsterblichen beim Weiqi","artist":"Dai Jin zugeschrieben","date":"Ming-Dynastie, 15.–16. Jahrhundert","place":"China","game":"Weiqi (Go)","medium":"Hängerolle; Tusche und Farben auf Seide","size":"175,2 × 106,7 cm","credit":"","p":["Eine große Hängerolle, dem Ming-Maler Dai Jin (um 1388–1462) zugeschrieben. Er stammte aus Zhejiang, war für kraftvolle Landschaften bekannt und galt später als Begründer der Zhe-Schule. Unter aufragenden Felsen und einem großen Baum sind die Menschen klein gemalt.","Im Schatten sitzen zwei Unsterbliche an einem gerasterten Weiqi-Brett, daneben ein Obstteller und ein Krug. Die kauernde Gestalt links erinnert an den Holzfäller, der Unsterblichen im Gebirge so lange beim Spiel zusah, bis sein Axtstiel verrottet war (die Lanke-Legende); der Museumstitel nennt jedoch nur Unsterbliche beim Weiqi."],"spots":[["Das Brett","Ein Brett mit Rand und feinem Raster."],["Der bärtige Unsterbliche","Ein Unsterblicher mit langem Bart, ruhig sitzend."],["Der Unsterbliche mit blauer Kappe","Er beugt sich übers Brett; am Knie eine Schale mit Steinen."],["Die kauernde Gestalt","Sie späht von links aufs Brett; vielleicht der Holzfäller der Legende."],["Obst und Krug","Teller und Krug jenseits des Bretts."],["Signatur und Siegel","Eine Signatur und zwei rote Siegel oben rechts."]]},"reise":{"title":"Die Reise um die Welt, zu Wasser und zu Lande","artist":"Anonym","date":"19. Jahrhundert","place":"Wohl deutscher Sprachraum","game":"Würfel-Wettlaufspiel um Einsätze","medium":"Lithografie","size":"42,5 × 33,7 cm","credit":"","p":["Ein Spielbogen mit dem Titel „Die Reise um die Welt, zu Wasser und zu Lande. Ein neues und unterhaltendes Würfelspiel“. Ein rundes Brett trägt die Felder 1 bis 41 mit Bildern von Ballon, Segelschiffen, Dampfschiff, Eisenbahn, Menschen verschiedener Völker und mehr. Unten rechts steht „No. 107“.","Darunter die Regeln auf Deutsch, Englisch, Niederländisch und Französisch. Jeder zahlt zuerst 15 Mark in die gemeinschaftliche Reisekasse, dann würfelt man der Reihe nach mit einem Würfel und setzt sein Zeichen. Ein größeres Bild gewinnt 2 Marken, eine Nummer ohne Bild kostet 2 Mark Strafe, und Nummer 41 gewinnt den ganzen Rest."],"spots":[["41: die Postkutsche","Das Ziel in der Mitte: eine Kutsche mit Reisenden und Kutscher."],["1: der Engländer","Das Startfeld, „Engländer“ mit Zylinder."],["Der Ballon","Ein Feld mit einem Ballon am Himmel."],["Das Segelschiff","Ein Schiff unter vollen Segeln."],["Die Eisenbahn","Eine qualmende Dampflokomotive."],["Die Spielregel","Die Regeln in vier Sprachen."]]},"huchten":{"title":"Das Würfelspiel um das Leben","artist":"Jan van Huchtenburg","date":"1680–1720","place":"Niederlande","game":"Würfel","medium":"Öl auf Leinwand","size":"67,5 × 76,0 cm","credit":"","p":["Ein Werk des für Schlachtenbilder bekannten niederländischen Malers Jan van Huchtenburg (1647–1733), unten links signiert. Der Museumstitel lautet „Das Würfelspiel um das Leben“. Vor einer Festung würfeln zwei Gefangene auf einer Trommel, umringt von Offizieren und Soldaten.","Hinten rechts steht ein Galgen, links schauen Soldaten von der Festungsmauer zu. Vermutlich losen verurteilte Soldaten mit Würfeln aus, wer hingerichtet wird. Ein Gefangener zeigt auf die Trommel, der andere kniet und blickt auf den Wurf."],"spots":[["Trommel und Würfel","Eine Trommel dient als Tisch für den Wurf."],["Der zeigende Gefangene","Stehend, er zeigt auf die Trommel."],["Der kniende Gefangene","Im weißen Hemd über die Trommel gebeugt."],["Der berittene Offizier","Mit Hut blickt er vom Pferd herab."],["Der Galgen","Der Galgen oben rechts."],["Soldaten auf der Mauer","Soldaten, die von der Mauer zusehen."]]},"vertu":{"title":"Das Spiel der Tugend (Spel der Deugd)","artist":"Jan Gerritsz. Visser (Entwurf J. Voorman)","date":"1798","place":"Niederlande","game":"Glücksspiel mit zwei Würfeln","medium":"Kupferstich, Radierung und Buchdruck","size":"56,9 × 38,0 cm","credit":"","p":["Ein großer Spielbogen mit niederländisch-französischem Titel „Das Spiel der Tugend“. In einem Säulentempel thront die Tugend, links steht der Wohlstand, rechts die Armut. An den Säulen hängen Medaillons von Tugenden wie Aufrichtigkeit, Dankbarkeit und Liebe, auf den Sockeln Laster wie Geiz, Hochmut und Faulheit.","Laut den Regeln darunter spielt man mit zwei Würfeln oder durch Losziehen. Mit Würfeln setzen alle zusammen 63 und würfeln reihum im Lauf der Sonne. Jeder Wurf bezeichnet eine Tugend oder ein Laster: Sechserpasch, die Tugend, nimmt den Topf, Einserpasch, das Laster, zahlt acht. Unter jedem Bild steht „T“ für Nehmen und „B“ für Zahlen."],"spots":[["Der Titel","„SPEL DER DEUGD“ im Giebel."],["Die Tugend","Die thronende Tugend in der Mitte; Sechserpasch nimmt alles."],["Der Wohlstand","Der Wohlstand mit Füllhorn."],["Das Laster","Einserpasch, das Laster: ein Kind mit erhobenem Becher."],["Der Geiz","Der Geiz auf dem Sockel; „B“ und die Würfel nennen die Zahlung."],["Die Spielregel","Die eng gedruckten Regeln unten."]]},"charros":{"title":"Die Charro-Schmuggler: ein Würfelspiel","artist":"José Guadalupe Posada","date":"Undatiert","place":"Mexiko","game":"Wettlaufspiel mit drei Würfeln","medium":"Lithografie","size":"29,9 × 40,4 cm","credit":"","p":["Ein Laufspiel mit Bildern von Posada, betitelt „LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS“ (Die Charro-Schmuggler / Würfelspiel). Unten steht die Druckerei A. Vanegas Arroyo, Mexiko; Posada signierte unten rechts. Charros, mexikanische Reiter, galoppieren mit Sombrero in den Ecken.","Mit Seil umrandete runde Felder winden sich übers ganze Brett, mit Tieren, Menschen, einem Zug und mehr. Die „Erklärung“ oben rechts nennt drei Würfel. Drei Einsen beim ersten Wurf gewinnen; der Totenkopf verliert; beim Hirsch bekommt man aus der Kasse, bei den Räubern zahlt man, und beim Löwen bleibt man stehen, bis ein anderer kommt."],"spots":[["Der Titel","„LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS“."],["Die Erklärung","Die Regeln unter „EXPLICACION“."],["Die Spieler","Leute an einem Tisch beim Brettspiel, unten links."],["Die Würfel","Drei Würfel in der Mitte des Bretts."],["Der Charro zu Pferd","Ein galoppierender Charro mit kreisendem Lasso."],["Die Druckerei","„IMPRENTA DE A. VANEGAS ARROYO, MÉXICO“."]]},"snuffwq":{"title":"Schnupftabakfläschchen mit Weiqi-Spielern","artist":"China","date":"Qing-Dynastie, Daoguang-Marke und -Periode (1820–50)","place":"China","game":"Weiqi (Go)","medium":"Porzellan mit Aufglasurmalerei","size":"Höhe 5,7 cm","credit":"","p":["Ein Fläschchen, in dem man im China der Qing-Zeit Schnupftabak bei sich trug. Laut Museum trägt es eine Daoguang-Regierungsmarke und stammt von 1820–50. Auf dem etwa sechs Zentimeter hohen weißen Porzellankörper sind Berglandschaft und Figuren in Aufglasurfarben gemalt.","Neben einem höhlenartigen Felsen sitzen zwei Alte an einem Weiqi-Brett auf blauem Gestell; der linke setzt gleich einen Stein. Hinter ihm schaut ein Knabe mit Stab zu. Das Motiv erinnert wohl an den Holzfäller, der Unsterblichen beim Spiel zusah."],"spots":[["Das Brett","Ein Brett auf blauem Gestell mit feinem Raster."],["Der bärtige Alte","Im violetten Gewand, die Hand zum Brett."],["Der Alte gegenüber","Rechts sitzend, die Hand erhoben."],["Der Knabe mit Stab","Er schaut von hinten zu."],["Die Grotte","Ein höhlenartiger Fels dahinter."],["Der Stöpsel","Ein grüner Stöpsel."]]},"ostade":{"title":"Tricktrackspieler in einer Schenke","artist":"Adriaen van Ostade","date":"1653","place":"Niederlande (Haarlem)","game":"Tricktrack (verwandt mit Backgammon)","medium":"Radierung","size":"8,5 × 7,4 cm","credit":"","p":["Eine handtellergroße Radierung des Haarlemer Malers Ostade, bekannt für Bauernszenen, unten signiert „A. ostade“. In einer dunklen Schenke fällt Licht aus einem Bleiglasfenster auf die Leute.","Am Tisch links sitzen zwei Männer am Tricktrackbrett, ein dritter schaut von hinten zu. Rechts lehnt ein Mann an der Wand, einen Becher in der Hand. Ein großer Krug liegt am Boden; es wirkt wie ein müßiger Nachmittag in der Schenke."],"spots":[["Das Brett","Ein Tricktrackbrett auf dem Tisch."],["Der linke Spieler","Ein Mann mit Hut vor dem Brett."],["Der rechte Spieler","Über das Brett gebeugt."],["Der Zuschauer","Ein Mann, der hinten steht und zuschaut."],["Der Ruhende","An der Wand sitzend, Becher in der Hand."],["Das Bleiglasfenster","Ein Rautenfenster, durch das das Licht kommt."]]},"lenain":{"title":"Die Würfelspieler","artist":"Nachfolger des Mathieu Le Nain","date":"1630–1680","place":"Frankreich","game":"Würfel","medium":"Öl auf Leinwand","size":"92,8 × 119,7 cm","credit":"","p":["Das Werk eines Nachfolgers von Mathieu, dem jüngsten der französischen Brüder Le Nain. Laut Museum befindet sich eine Skizze einer ähnlichen Komposition von Gabriel de Saint-Aubin in der Bibliothèque nationale in Paris.","Drei Männer sitzen im Freien um ein kleines rundes Tischchen und würfeln; zwei sehen zu, der linke drückt eine Flasche an sich. Rechts stehen zwei schlanke Windhunde, dahinter öffnet sich eine weite Landschaft. Die kleinen weißen Dinge auf dem Tisch sind die Würfel."],"spots":[["Würfel auf dem Tisch","Würfel auf dem runden Tisch."],["Der Mann mit hellem Hut","Sitzend greift er nach dem Wurf."],["Der Mann in Schwarz","Ein junger Mann, die Hand in der Hüfte."],["Der Junge dahinter","Er verfolgt das Spiel hinter dem Tisch."],["Der Mann mit der Flasche","Links lächelt er uns an."],["Die zwei Windhunde","Schlanke Hunde rechts."]]},"tunisie":{"title":"Kartenspiel vor einem arabischen Café (tunesische Abteilung, Weltausstellung Antwerpen)","artist":"Anonym (Druck Ch. Bernhoeft)","date":"1894","place":"Belgien (Antwerpen)","game":"Kartenspiel","medium":"Lichtdruck","size":"15,4 × 21,6 cm","credit":"","p":["Eine von 49 Tafeln zur Weltausstellung Antwerpen 1894, oben mit „EXPOSITION UNIVERSELLE D’ANVERS 1894“, unten „Tunesien. Kartenspiel vor einem arabischen Café“. Gedruckt hat sie Bernhoeft, Hoffotograf in Luxemburg.","Aufgenommen auf einem Platz mit Kuppeln und Turm, gebaut für die tunesische Abteilung der Ausstellung. Männer in tunesischer Kleidung spielen an kleinen gekachelten Tischen Karten; einer raucht Wasserpfeife, daneben ein Tablett mit Tassen. Rechts sitzen Besucher im Anzug – vermutlich eine Schau vom Leben in einem fernen Land."],"spots":[["Der Kartentisch","Männer mit Karten an einem gekachelten Tischchen."],["Die Wasserpfeife","Der Schlauch der Wasserpfeife des linken Mannes."],["Besucher im Anzug","Männer im Anzug rechts, vermutlich Ausstellungsgäste."],["Das Tassentablett","Kleine Tassen unter dem Tisch."],["Kuppeln und Turm","Für die Ausstellung errichtete Bauten im tunesischen Stil."],["Die Bildunterschrift","„TUNISIE“ und „PARTIE DE CARTES DEVANT UN CAFÉ ARABE“."]]},"laghouat":{"title":"Kaids aus der Umgebung von Laghouat","artist":"Anonym","date":"1880–1890","place":"Algerien (bei Laghouat)","game":"Wohl Domino","medium":"Albuminabzug","size":"20,9 × 27,0 cm","credit":"","p":["Eine Fotografie mit dem Titel „Algerische Typen. Kaids aus der Umgebung von Laghouat“, in ein Album geklebt und mit der Nummer „239“ bedruckt. Kaid war im französisch beherrschten Algerien der Titel eines örtlichen Oberhaupts.","Männer in weißen Gewändern sitzen vor einer Lehmmauer auf einer Matte und legen lange Steine auf einem niedrigen Tisch aus. Der Anordnung nach wohl Domino, auch wenn der Museumsdatensatz nur „ein Spiel“ nennt. Vorn ein Teetablett und die ausgezogenen Pantoffeln."],"spots":[["Steine auf dem niedrigen Tisch","Lange Steine in einer Reihe auf dem Tisch."],["Das Teetablett","Gläser und Kanne auf einem Tablett vorn."],["Die Pantoffeln","Neben der Matte abgestellte Schuhe."],["Die stehende Gestalt","Jemand steht an der Mauer und schaut zu."],["Die Lehmmauer","Die raue Erdmauer dahinter."],["Die Matte","Die geflochtene Matte, auf der sie sitzen."]]},"hangong":{"title":"Palastdamen (Frühlingsmorgen im Han-Palast), Ausschnitt","artist":"Kopie nach Qiu Ying","date":"Qing-Dynastie (1644–1911)","place":"China","game":"Weiqi (Go)","medium":"Querrolle; Tusche und Farben auf Seide","size":"36,2 × 454,4 cm (ganze Rolle)","credit":"","p":["Ein Ausschnitt aus einer über viereinhalb Meter langen Querrolle, einer Kopie der Qing-Zeit nach einer Komposition des Ming-Malers Qiu Ying (1494–1552). In einem Palast an einem Frühlingstag schaukeln Hofdamen, Mädchen und Dienerinnen, spielen, bewundern Pfingstrosen, musizieren, spielen die Qin und füttern einen Papagei und Fische.","In dieser Szene sitzen sich zwei Frauen hinter einer Brüstung an einem Weiqi-Brett gegenüber, andere beugen sich zum Zusehen vor. Vorn steht ein Gelehrtenstein in einem lotosförmigen Becken, Dienerinnen tragen Instrumente und Bündel. Wie das Museum bemerkt, idealisiert die Rolle das Leben der Frauen in den inneren Gemächern."],"spots":[["Das Brett","Ein Weiqi-Brett auf einem Tisch hinter der Brüstung."],["Die setzende Spielerin","Eine Frau in Blasslila greift zum Brett."],["Die Zuschauerinnen","Frauen, die sich über die Partie beugen."],["Die Dame mit Fächer","Eine Frau mit rundem Fächer zwischen den Säulen."],["Der Gelehrtenstein","Ein blauer Stein in einem Lotosbecken."],["Die Dienerin mit Instrument","Eine Dienerin mit wohl einer Pipa."]]},"homerbg":{"title":"Backgammon","artist":"Winslow Homer","date":"um 1877","place":"Vereinigte Staaten","game":"Backgammon","medium":"Holzstich","size":"","credit":"","p":["Ein Holzstich nach einer Zeichnung des amerikanischen Malers Winslow Homer (1836–1910), der in jungen Jahren viele Illustrationen für solche Drucke zeichnete. Darunter steht „396.—BACKGAMMON.—WINSLOW HOMER.“ – wohl ein nummeriertes Blatt aus einem Buch oder einer Zeitschrift.","Zwei Frauen sitzen einander auf einem verzierten Sofa gegenüber und spielen Backgammon auf einem Brett, das über ihren Knien liegt. Auf dem Brett liegt ein runder weißer Gegenstand; was er ist, bleibt unklar. Die Falten der langen Röcke und die geschwungenen Sofalehnen sind in feinen Linien gestochen."],"spots":[["Das Brett","Das Brett über den Knien der beiden Frauen."],["Die Frau links","Mit hochgestecktem Haar greift sie zum Brett."],["Die Frau rechts","Sie beugt sich vor und studiert das Brett."],["Die Sofalehne","Eine schneckenförmige Armlehne."],["Die Röcke","Lange Röcke mit fein gestochenen Falten."],["Die Unterschrift","„396.—BACKGAMMON.—WINSLOW HOMER.“ darunter."]]},"chessst":{"title":"Mann und Frau beim Schach (Stereofoto)","artist":"Anonym","date":"1852–1858","place":"Unbekannt","game":"Schach","medium":"Stereofotografie, koloriert","size":"8,3 × 16,5 cm","credit":"","p":["Ein Bildpaar als Stereofotografie, englisch „The Chess Players“ genannt. Im Stereoskop scheinen Brett und Figuren plastisch hervorzutreten. Über das Schwarz-Weiß-Bild wurde Farbe gelegt, auf den roten Vorhang und das gelbe Kleid.","Die Frau in Gelb hat die Hand an einer Figur, der Mann gegenüber, von hinten gesehen, betrachtet das Brett. Rote und weiße Figuren stehen mitten in der Partie, doch die Szene wurde wohl im Atelier gestellt. Solche Stereobilder häuslicher Szenen wurden um die Mitte des 19. Jahrhunderts viel verkauft."],"spots":[["Brett und Figuren","Rote und weiße Figuren auf dem Schachbrett."],["Die ziehende Hand","Die Hand der Frau an einer Figur."],["Die Frau","Im gelben Kleid mit weißem Kragen, über das Brett geneigt."],["Der Mann","Mit dem Rücken zu uns sitzend."],["Der rote Vorhang","Der kolorierte Vorhang dahinter."],["Das zweite Bild","Die rechte Ansicht; im Stereoskop gewinnt das Paar Tiefe."]]},"corrida":{"title":"Stierkampf-Würfelspiel (Corrida de Toros)","artist":"José Guadalupe Posada","date":"1898","place":"Mexiko","game":"Würfel-Wettlaufspiel mit zwei Würfeln um Einsätze","medium":"Autotypie im Hochdruck auf Velinpapier","size":"40,4 × 30,0 cm","credit":"","p":["Ein Laufspiel mit Bildern von Posada, betitelt „CORRIDA DE TOROS“ (Stierkampf). Die Felder laufen spiralförmig und zeigen der Reihe nach Figuren und Augenblicke des Stierkampfs, von Feld 1 außen bis zur Mitte. In der Mitte steht eine Arena, unten der Name der Druckerei von Antonio Vanegas Arroyo.","Laut der „Erklärung“ unten setzen zwei oder mehr Spieler ein und ziehen mit zwei Würfeln. Fünf, der „Stabsprung“, führt nach 10; zwölf, „der Picador wird aufgespießt“, zahlt und setzt aus; 28, der „Brustpass“, beginnt von vorn. Wer 32 erreicht, „den Stier hinausschleifen“, gewinnt alle Einsätze."],"spots":[["Der Titel","Die Worte „CORRIDA DE TOROS“."],["Die Arena","Das Arenagebäude im Zentrum der Spirale."],["Feld 1","Der Start am Eingang der Spirale."],["Der Stierkopf","Ein gehörnter Stierkopf oben rechts."],["Der Torero","Das Bildnis eines Toreros unten links."],["Die Erklärung","Die „EXPLICACION“ am Fuß."]]},"ambrocards":{"title":"Drei Männer beim Kartenspiel","artist":"Unbekannt (amerikanisch)","date":"1865","place":"Vereinigte Staaten","game":"Kartenspiel","medium":"Ambrotypie","size":"14,0 × 11,0 cm","credit":"","p":["Eine Ambrotypie ist ein dünnes Glasnegativ, schwarz hinterlegt, sodass es als Positiv erscheint. Billiger als die Daguerreotypie, war sie in Amerika in den 1850er- und 60er-Jahren weit verbreitet. Diese liegt hinter einem goldenen Passepartout in einem mit rotem Samt ausgeschlagenen Etui.","Vor schlichtem Hintergrund sitzen drei Männer mit Karten in der Hand an einem Tischchen. Der linke trägt eine Melone, der rechte eine Mütze, beide mit Zigarre im Mund; der Mann in der Mitte im dunklen Jackett blickt uns an. Wohl posierten sie für die Kamera wie mitten im Spiel."],"spots":[["Die Hände","Hände mit Karten über dem Tisch."],["Der Mann mit Melone","Links, mit Zigarre."],["Der Mann in der Mitte","Im dunklen Jackett, er blickt uns an."],["Der Mann mit Mütze","Rechts, mit Zigarre."],["Das goldene Passepartout","Der geprägte Goldrahmen um das Bild."],["Das Etui","Das mit rotem Samt ausgeschlagene Etui."]]},"morphy":{"title":"Paul Morphy, der Schachmeister","artist":"Winslow Homer","date":"1859","place":"Vereinigte Staaten","game":"Schach","medium":"Holzstich","size":"","credit":"","p":["Ein Porträt-Holzstich mit der Unterschrift „PAUL MORPHY, THE CHESS CHAMPION“ nach einer Zeichnung von Winslow Homer (1836–1910), damals ein junger Illustrator. Morphy (1837–1884) aus New Orleans bereiste 1858–59 Europa, schlug einen führenden Meister nach dem anderen und kehrte berühmt heim.","Der junge Morphy sitzt und legt die linke Hand an den Rand eines Bretts, neben König, Turm, Bauern und anderen Figuren. Entstanden 1859, als er gefeiert zurückkehrte, wurde es wohl als Illustration in einer Zeitung oder Zeitschrift gedruckt."],"spots":[["Die Figuren","König, Turm, Bauern und andere auf dem Brett."],["Die Hand am Brett","Seine linke Hand am Brettrand."],["Morphys Gesicht","Der Meister, kaum über zwanzig."],["Die Fliege","Ein ordentlicher Kragen."],["Die Hand auf dem Knie","Seine rechte Hand ruht auf dem Knie."],["Der Titel","„PAUL MORPHY, THE CHESS CHAMPION“ darunter."]]},"dutton":{"title":"Die Familie Dutton im Salon von Sherborne Park, Gloucestershire","artist":"Johann Zoffany","date":"um 1772","place":"England","game":"Kartenspiel","medium":"Öl auf Leinwand","size":"101,5 × 127,0 cm","credit":"","p":["Ein Werk von Johann Zoffany (1733–1810), einem in Deutschland geborenen Maler, der in England Karriere machte. Das „Conversation Piece“, das Familien ungezwungen zeigt, entstand im England des 18. Jahrhunderts und war sehr beliebt. Schauplatz ist der Salon von Sherborne Park in Gloucestershire.","Laut Museum überlegen Vater und Tochter, Mutter und Sohn ihren nächsten Zug in einem Kartenspiel. Die Familie hatte kurz zuvor einen nahen Menschen verloren: Die Eltern tragen tiefe Trauer in Schwarz, die Kinder Halbtrauer in Malve, Weiß und Grau."],"spots":[["Der Spieltisch","Ein grün bespannter Tisch mit Karten."],["Der Vater","In Schwarz, mit seinen Karten."],["Die Tochter","In Weiß, sie betrachtet ihr Blatt."],["Der Sohn","In Grau, mit seinen Karten."],["Die Mutter","In schwarzer Trauerkleidung."],["Der Kamin","Ein Marmorkamin mit brennendem Feuer."]]},"whist":{"title":"Die Weihnachts-Akademiker: eine Kombinationspartie Whist","artist":"James Bretherton (wohl nach H. W. Bunbury)","date":"1773","place":"England","game":"Whist (Karten)","medium":"Radierung","size":"26,5 × 39,6 cm","credit":"","p":["Laut Museum eine Satire auf die Gelehrten von Cambridge. Unten links scheint „H. W. Bunbury del. 1772“ zu stehen, unten rechts „J. Bretherton f.“; das Blatt erschien 1773 bei einem Laden in der New Bond Street in London. An der Wand hängen Doktorhüte.","Vier Herren spielen Whist und schneiden einander Grimassen. Whist spielen zwei Paare gegeneinander, die „Kombinationspartie“ des Titels ist also wohl ein Wortspiel. Hinten macht einer mit den Fingern eine Spottgeste über dem Kopf eines anderen. Zwei Diener und zwei Hunde sind dabei."],"spots":[["Karten auf dem Tisch","Ausgespielte Karten."],["Der Gelehrte mit Perücke","Ein Gelehrter mit großer Perücke, die Karten an der Brust."],["Die Fingergeste","Ein Mann hinten hebt die Finger über einen Kopf."],["Die Magd","Eine Dienerin mit Hut und Tablett."],["Die Doktorhüte","Universitätshüte an der Wand."],["Der Hund rechts","Ein kleiner kläffender Hund unten rechts."]]},"hey":{"title":"Drei Männer beim Schach","artist":"Paul Hey","date":"1877–1952","place":"Deutschland","game":"Schach","medium":"Druckgrafik (wohl Radierung)","size":"19,3 × 26,0 cm","credit":"","p":["Ein Blatt des deutschen Malers und Illustrators Paul Hey (1867–1952). Drei ältere Männer beugen sich über ein Schachbrett; feine, geschichtete Linien zeichnen tiefe Falten und weiße Bärte.","Wie der Museumsdatensatz vermerkt, stützt der linke das Kinn in die Hand, der rechte hält eine Zigarre und greift über die Figuren. Links auf dem Tisch stehen zwei Kaffeetassen, ein Glas und eine Streichholzschachtel. Wohl eine Partie im Café."],"spots":[["Das Schachbrett","Brett und Figuren auf dem Tisch."],["Der Mann mit der Hand am Kinn","Weißbärtig, in Gedanken."],["Der Mann in der Mitte","Vorgebeugt, greift er nach einer Figur."],["Der Mann rechts","Er schaut von hinten zu."],["Die Hand mit der Zigarre","Eine Zigarre zwischen den Fingern."],["Kaffee und Streichhölzer","Zwei Tassen, ein Glas und eine Streichholzschachtel links."]]},"artful":{"title":"Die listige Karte oder eine zu viel für Großmutter. Herz ist Trumpf!","artist":"Anonym","date":"1852–1863","place":"Wohl Großbritannien","game":"Kartenspiel","medium":"Stereofotografie, koloriert","size":"8,4 × 17,4 cm","credit":"","p":["Der englische Titel lautet „The artful card, or, one too many for granny. Hearts are trumps!“ Eine komische kleine Szene, in der die Großmutter mit einer listigen Karte ausgetrickst wird, als Stereobildpaar. Der englische Titel lässt vermuten, dass es in Großbritannien entstand.","Am runden Tisch spielen Großmutter und ein Mädchen Karten, während die junge Frau in Grün mit ihrem Blatt in der Hand von einem jungen Mann umarmt wird. „Herz ist Trumpf“ spielt wohl auf die Kartenfarbe und die Liebe an. Das Zimmer mit Spinnrad und Geschirrschrank ist sicher eine Atelierkulisse."],"spots":[["Das Blatt der jungen Frau","Die Karten der Frau in Grün."],["Der junge Mann","Die Hand von hinten auf ihrer Schulter."],["Die Großmutter","Eine ältere Frau mit Kopftuch, den Blick auf den Karten."],["Das Mädchen","Lächelnd spielt sie eine Karte aus."],["Der Tisch","Ein runder Tisch mit Karten und Kleinigkeiten."],["Der Geschirrschrank","Ein Glasschrank mit Geschirr."]]},"cezcards":{"title":"Studie zu den Kartenspielern","artist":"Paul Cézanne","date":"1890–92","place":"Frankreich","game":"Kartenspiel","medium":"Aquarell und Grafit auf beigem Velinpapier","size":"36,2 × 48,5 cm","credit":"","p":["In den 1890er-Jahren malte Cézanne in Aix in Südfrankreich mehrere Bilder kartenspielender Männer. Dies ist eine Aquarellstudie zu der Reihe: Ein schnurrbärtiger Mann mit Hut sitzt am Tisch und betrachtet sein Blatt.","Über Grafitlinien fassen dünne blaue und graue Lasuren die Falten der Jacke und das Gewicht des Körpers. Die rechte Seite und das Tischende bleiben unvollendet; Farbe liegt nur um die Figur. Seine Modelle sollen Arbeiter aus der Gegend gewesen sein."],"spots":[["Das Gesicht","Mit gesenktem Blick unter dem Hut betrachtet er die Karten."],["Die Karten","In beiden Händen gehaltene Karten."],["Der Tisch","Ein nur mit Bleistift gezeichneter Tisch."],["Der Stuhl","Die Stuhllehne links."],["Die Jacke","Falten aus Blau und Grau aufgebaut."],["Das Unvollendete","An den Tischbeinen bleiben nur die Linien."]]},"vuillardck":{"title":"Die Damepartie, aus Landschaften und Interieurs","artist":"Édouard Vuillard","date":"1899","place":"Frankreich","game":"Dame","medium":"Farblithografie auf grauelfenbeinfarbenem Chinapapier","size":"36,9 × 28,5 cm","credit":"","p":["Das erste Blatt von Landschaften und Interieurs, einer Mappe mit Farblithografien des Malers Vuillard, verlegt vom Kunsthändler Ambroise Vollard und gedruckt vom Lithografen Auguste Clot.","In einem Raum voller gemusterter Tapete sitzt ein bärtiger Mann am Damebrett, während eine Frau im karierten Kleid steht, die Hand am Kinn, und zuschaut. Figuren, Tapete und Sofa verschmelzen zu flachen Farben und Mustern; nur die schwarz-weißen Felder des Bretts treten scharf hervor."],"spots":[["Das Brett","Das schwarz-weiße Damebrett."],["Der bärtige Mann","Am Brett sitzend."],["Die stehende Frau","Im karierten Kleid, die Hand am Kinn."],["Die Tapete","Tapete voller wirbelnder Linien."],["Das Blumenkissen","Gemusterter Stoff unten links."],["Die Lampe","Eine schlanke Lampenform an der Wand."]]},"cruikchess":{"title":"Schachpartie","artist":"George Cruikshank nach Captain Frederick Marryat","date":"1814","place":"England","game":"Schach","medium":"Handkolorierte Radierung","size":"23,8 × 34,5 cm","credit":"","p":["Ein Blatt des englischen Karikaturisten Cruikshank nach einer Skizze von Marryat, Marineoffizier und später Romancier, verlegt in London von Hannah Humphrey. Unten steht der Titel „GAME of CHESS“.","An einem Tisch mit Kerzen sitzen sich zwei ältere Herren am Schachbrett gegenüber. Hinter jedem steht ein Zuschauer: Der linke legt den Finger an die Lippen, der rechte späht durch ein Lorgnon aufs Brett. Vermutlich ein Spott auf Kiebitze, die nicht schweigen können."],"spots":[["Das Brett","Das Schachbrett mit schwarzen und weißen Figuren."],["Die Kerzen","Zwei Kerzen beleuchten das Brett."],["Der Mann, der „Pst“ macht","Ein Zuschauer mit Finger an den Lippen."],["Der Mann mit Lorgnon","Ein Zuschauer, der durchs Glas späht."],["Der schlafende Hund","Ein Hund schläft unter dem Tisch."],["Der Titel","„GAME of CHESS“ am Fuß."]]},"domino98":{"title":"Frau und Kind beim Dominospiel am Tisch","artist":"Unbekannt (amerikanisch)","date":"um 1898","place":"Vereinigte Staaten","game":"Domino","medium":"Albuminabzug auf Glas aufgezogen","size":"40,8 × 51,1 cm","credit":"","p":["Eine große Fotografie, wohl aus einem amerikanischen Atelier, auf Glas aufgezogen. Eine Frau in Weiß und ein lockiges Mädchen sitzen an einem kleinen, mit Blumen geschmückten Tisch.","Dominosteine liegen auf dem Tisch, die Frau legt gerade einen an. Das Mädchen stützt das Kinn in die Hand und schaut zu. Vorhänge, verzierter Schrank und Bilder an der Wand sind wohl eine Atelierkulisse."],"spots":[["Die Steine","Weiße Dominosteine auf dem Tisch."],["Das Mädchen","Das Kinn in der Hand, schaut es zu."],["Die Frau","In Weiß, legt einen Stein an."],["Die Blumen","Eine Blumenvase auf dem Tisch."],["Der Schrank","Ein verzierter Schrank hinten rechts."],["Die Aufschrift","Weiße Schrift unten rechts."]]},"langkat":{"title":"Albert Glaser beim Kartenspiel mit zwei Freunden auf einem Boot, Langkat, Sumatra","artist":"Anonym (H. Ernst & Co.)","date":"1895–1905","place":"Indonesien (Langkat, Sumatra)","game":"Kartenspiel","medium":"Fotografie","size":"17,5 × 22,8 cm","credit":"","p":["Eine Fotografie aus Langkat im Norden Sumatras. Unten rechts trägt sie den Blindstempel des Ateliers „H. Ernst & Co. / Bindjey Langkat“, auf der Rückseite steht handschriftlich, der Mann in der Mitte sei Albert Glaser, Bruder einer Dame.","Auf dem Deck eines Bootes unter einem Sonnendach sitzen drei weiß gekleidete Männer am Tisch, Karten in der Hand. Auf dem Tisch liegen Karten und münzenartige Stücke, neben dem rechten Mann steht eine Flasche. Weiße Kleidung und Sonnendach erzählen vom Leben in heißem Klima."],"spots":[["Auf dem Tisch","Ausgeteilte Karten und münzenartige Stücke."],["Glaser","Der Mann in der Mitte fächert seine Karten; die Rückseite nennt ihn."],["Der Mann links","Halb von hinten, mit Karten."],["Der Mann rechts","Mit Schnurrbart, Karten in der Hand."],["Die Flasche","Eine Flasche neben dem rechten Mann."],["Das Sonnendach","Laubgehänge am Sonnendach."]]},"chatur":{"title":"Eine Partie Chaturanga","artist":"Anonym","date":"1805–1815","place":"Indien","game":"Chaturanga","medium":"Gouache und Gold, Pinsel","size":"16,2 × 9,8 cm (Bild)","credit":"","p":["Eine indische Miniatur. Laut Museumsdatensatz spielen zwei Frauen Chaturanga, ein Brettspiel, während eine Dienerin einen Fliegenwedel hält. Chaturanga ist ein altes indisches Brettspiel und gilt als Vorfahr des Schachs.","Unter weißen Bögen, auf einem roten Teppich, sitzen sich eine Frau in Dunkelblau und eine in Orange an einem karierten Brett gegenüber. Die Frau in Orange streckt die Hand aus, als spräche sie. Das Bild ist von einem dunkelroten, schwarz-weiß gerahmten Rand umgeben."],"spots":[["Das Brett","Ein kariertes Brett auf dem roten Teppich."],["Die Frau in Blau","Mit Goldschmuck, sie greift zum Brett."],["Die Frau in Orange","Gegenüber, mit ausgestreckter Hand."],["Die Dienerin","Hinten stehend."],["Der Fliegenwedel","Von der Dienerin erhoben."],["Der rote Rand","Ein dunkelroter, schwarz-weiß gesäumter Rahmen."]]},"shabbarat":{"title":"Abend in den Frauengemächern","artist":"Anonym","date":"1760–1770","place":"Indien","game":"Chaupar (Pachisi)","medium":"Gouache und Gold, Pinsel","size":"34,3 × 25,6 cm","credit":"","p":["Eine indische Miniatur. Laut Museumsdatensatz spielen vier Frauen im weiten Hof eines Palastes ein Brettspiel, Chaupar oder Pachisi genannt. Sie sitzen um ein kreuzförmiges Stoffbrett.","Die Frau vorn rechts hält drei längliche Würfel, bereit zum Wurf. Neben ihr, an ein Polster gelehnt, sitzt die vornehmste Dame. Es ist Nacht, doch überall stehen Lampen auf der Terrasse, und unzählige Lichter säumen die fernen Stadtmauern. Der Datensatz vermutet, dass das islamische Fest Schab-e Barat gefeiert wird."],"spots":[["Das Kreuzbrett","Das kreuzförmige Brett am Boden."],["Die Frau mit den Würfeln","Vorn, mit länglichen Würfeln."],["Die Dame am Polster","Die ranghöchste Dame."],["Die Dienerin","Sie naht mit einem Tablett."],["Eine Lampe","Eine Kerze unter einer Glasglocke."],["Der ferne Pavillon","Ein Garten mit Brunnen, ein Pavillon und die Lichter der Stadt."]]},"govase":{"title":"Eiförmige Vase mit Go spielenden Frauen","artist":"Anonym (Siegel „Tang Jintang“)","date":"1724","place":"China (Guangdong)","game":"Go (Weiqi)","medium":"Porzellan mit Aufglasurfarben und Vergoldung","size":"Höhe 15,3 cm","credit":"","p":["Eine chinesische Vase aus sehr dünnem Porzellan, mit Emailfarben bemalt. Auf der Rückseite steht: „Bild einer Partie Go, gemalt am Tag des Blumenfestes im Jahr jiachen, in einem behaglichen Haus am Perlfluss in Lingnan“, dazu das rote Siegel „Tang Jintang“. Sie gehörte zur Porzellansammlung des Haager Sammlers Jean Theodore Royer.","Zwei Frauen sitzen sich an einem Go-Brett auf einem Tisch gegenüber; die linke hält eine Steinschale. Rechts beugen sich zwei Frauen und zwei Kinder zum Zuschauen vor. Auf dem Gestell dahinter stehen Antiquitäten, darunter eine Vase mit Pfauenfedern und Koralle."],"spots":[["Das Brett","Ein Go-Brett auf dem Tisch mit schwarzen und weißen Steinen."],["Die Spielerin links","Mit Steinschale, zeigend."],["Die Spielerin rechts","Über das Brett gebeugt."],["Die Zuschauerinnen","Frauen, die von hinten zusehen."],["Pfauenfedern und Koralle","In einer Vase auf dem Gestell."],["Die Steinschale","In der Hand der linken Frau."]]},"yokihi":{"title":"Ein Mann spielt Backgammon mit einer Dame (Kaiser Xuanzong und Yang Guifei)","artist":"Anonym (Surimono)","date":"1822","place":"Japan","game":"Ban-Sugoroku (japanisches Backgammon)","medium":"Farbholzschnitt mit Metallpigmenten","size":"21,6 × 19,1 cm","credit":"","p":["Ein Surimono, ein Luxusdruck, der Bild und Gedicht verbindet, auf dickem Papier mit Metallpulver gedruckt und von Dichtern als Geschenk für Freunde in Auftrag gegeben. Dieser trägt ein Gedicht und den Dichternamen Tachibana no Goen.","Laut Museumsdatensatz spielt der Tang-Kaiser Xuanzong (685–762) mit seiner Lieblingskonkubine Yang Guifei (719–756) Sugoroku, ein mit Backgammon und Tricktrack verwandtes Spiel. Auf einem kastenförmigen Brett auf einem roten Gestell stehen schwarze und weiße Steine."],"spots":[["Das Brett","Ein kastenförmiges Sugoroku-Brett auf rotem Gestell."],["Yang Guifei","Mit Blumen im Haar, die Hand auf dem Brett."],["Xuanzong","Die Hand am Kinn, er betrachtet das Brett."],["Das Gedicht","Ein Gedicht und der Dichtername oben links."],["Der Wandschirm","Ein Wandschirm mit Bergen dahinter."],["Signatur und Siegel","Signatur und rotes Siegel unten rechts."]]},"disderi":{"title":"Männer in Seefahrerkostüm beim Kartenspiel","artist":"Disdéri & Cie","date":"1850–1890","place":"Frankreich (Paris)","game":"Kartenspiel","medium":"Albuminabzug (Carte de visite)","size":"8,6 × 5,3 cm","credit":"","p":["Eine Fotografie im Carte-de-visite-Format aus einem Album, rückseitig bedruckt mit „Disdéri & Cie, 8 Boulevard des Italiens, Paris“. Disdéri machte die Carte de visite populär, kleine Porträts, die wie Visitenkarten in Mengen abgezogen wurden.","Männer in altmodischer Tracht – Dreispitz, langer Rock, weiße Strümpfe – spielen an einem verzierten Tisch Karten. Der Museumsdatensatz spricht von Seefahrerkostüm, doch es ist wohl ein Theater- oder Maskenkostüm. Der Mann in der Mitte steht auf, um auf den Tisch zu blicken."],"spots":[["Der Tisch","Ein Tisch mit verziertem Rand, darauf Karten und Becher."],["Der stehende Mann","Im Dreispitz beugt er sich über den Tisch."],["Der Mann links","Sitzend, Karten in der Hand."],["Der Mann rechts","Im Dreispitz, Karten in der Hand."],["Schnallenschuhe","Weiße Strümpfe und Schnallenschuhe."],["Der goldene Rahmen","Der Goldrand des Kartons."]]},"gans":{"title":"Gänsespiel (Spirale mit 74 Feldern)","artist":"Jan Oortman (d. Ä.) nach Entwurf von Daniel Willem Stoopendaal","date":"1763–1823","place":"Niederlande","game":"Gänsespiel (Würfelwettlauf)","medium":"Holzschnitt, blau, rot und grün koloriert","size":"40,8 × 46,8 cm","credit":"","p":["Ein in den Niederlanden gedrucktes Spiralspiel. Laut Museum laufen die Felder von 1 bis 74, einige mit Bildern. Jan Oortman schnitt den Stock nach einem Entwurf von Stoopendaal, dessen Name unten rechts mit „invenit“ steht.","Das Ziel, Feld 74, ist ein Tempel am Meer bei Sonnenuntergang in der Mitte. Felder tragen Wörter wie „LEER GELD“ (Lehrgeld), „DWAALWEG“ (Irrweg) und „DOMHEID / WYSHEID“ (Dummheit / Weisheit) sowie ein Skelett mit Sense, „EINDE“ (das Ende) – wohl ein moralisches Spiel vom Lebensweg."],"spots":[["74: der Tempel","Das Ziel: ein Tempel am Ufer bei Sonnenuntergang."],["1: der Start","Das erste Feld unten links."],["Lehrgeld","Ein Feld „LEER GELD“, wohl zum Bezahlen."],["Der Irrweg","Ein Waldweg mit „DWAALWEG“."],["Das Ende","Ein Skelett mit Sense: „EINDE“."],["Die Würfel","Ein Feld mit zwei Würfeln."]]},"merelle":{"title":"Mühlespiel und Drachen","artist":"Claudine Stella nach Jacques Stella","date":"1657","place":"Frankreich (Paris)","game":"Merelle (Mühle)","medium":"Kupferstich","size":"11,7 × 14,1 cm","credit":"","p":["Blatt 17 einer Folge von Kinderspielen, gestochen von Claudine Stella nach Entwürfen ihres Onkels, des Malers Jacques Stella. Laut Museum stammt es aus einem Album mit 51 Stichen. Es spielen pausbäckige nackte Kinder, Putten.","Vorn links spielen sie Merelle (Mühle) auf einem in einen Steinblock geritzten Brett. Rechts auf dem Boden die Linien des Franc du carreau, bei dem man Münzen auf Felder wirft; weiter hinten rennt ein Kind mit einem Drachen. Die Verse darunter sagen, dass sich jeder müht, gut zu spielen."],"spots":[["Das Mühlebrett","Ein in Stein geritztes Brett mit Steinen."],["Der Drachen","Ein Drachen hoch in der Luft."],["Das Kind mit dem Drachen","Es rennt mit der Schnur."],["Franc du carreau","Quadrate und Diagonalen am Boden."],["Das zeigende Kind","Mit etwas in der Hand zeigt es auf die Linien."],["Der Titel","„LA MERELLE, & LE CERF VOLANT“."]]},"feldcards":{"title":"Kartenspiel am Gartentisch (Stereofoto)","artist":"Anonym","date":"1850–1880","place":"Unbekannt (Stempel einer Groninger Firma auf der Rückseite)","game":"Kartenspiel","medium":"Albuminabzug (Stereofotografie)","size":"8,5 × 17,0 cm","credit":"","p":["Eine Stereofotografie einer Familie oder Freundesrunde beim Kartenspiel an einem Gartentisch, vor einem efeuberankten Spalier. Rückseitig steht der Stempel von Feldbrugge & Co., Groningen (Niederlande), vermutlich der Laden oder Verlag, der sie verkaufte.","Der bärtige Mann links hebt eine Karte hoch, gleich knallt er sie auf den Tisch. Ein Mann mit aufgestütztem Kopf, ein Junge mit seinem Blatt, ein weißhaariger Alter und eine Frau, die von hinten zuschaut, vervollständigen den Moment. Da alle lange stillhalten mussten, ist die Szene wohl gestellt."],"spots":[["Die erhobene Karte","Die Karte, die der Bärtige hochhält."],["Auf dem Tisch","Bereits ausgespielte Karten."],["Das Blatt des Jungen","Die Karten des Jungen, von hinten gesehen."],["Der Alte","Der weißhaarige Mann rechts."],["Die zuschauende Frau","Sie steht dahinter und verfolgt das Spiel."],["Der bestickte Stuhl","Ein Stuhl vorn mit geblümtem Bezug."]]},"tempel":{"title":"Spielbrett „Der Tempel des Glücks“","artist":"Anonym","date":"1816","place":"Niederlande","game":"Würfel-Laufspiel","medium":"Holzschnitt mit Text im Buchdruck","size":"43,0 × 48,5 cm","credit":"","p":["Ein Spielbogen mit den Feldern 1 bis 74 in einer Spirale. In der Mitte steht ein runder Tempel am Meer; das in derselben Sammlung erhaltene Regelblatt nennt ihn „Der Tempel des Glücks“ und spricht von einem Wurfspiel, also einem Würfelspiel.","Die meisten Felder sind leere Kreise, doch hier und da finden sich Rosen, Dornen, Würfel, ein Gittertor, eine Fähre und anderes, dazu Wörter wie „LEER GELD“ (Lehrgeld), „DOMHEID“ (Dummheit) und „WYSHEID“ (Weisheit). Wohl ein moralisches Laufspiel, das über gute und schlechte Taten zum Tempel führt."],"spots":[["Der Tempel des Glücks","Der Tempel am Meer in der Mitte: Feld 74, das Ziel."],["Feld 1","Der Start unten links."],["Lehrgeld","Ein Feld mit „LEER GELD“."],["Die Würfel","Zwei Würfel in der obersten Reihe."],["Die Fähre","Das Bild „OVER HAAL“ (Überfahrt) unten."],["Dummheit und Weisheit","Die Wörter „DOMHEID“ und „WYSHEID“ rechts."]]},"verkeer":{"title":"Miniatur-Verkeerbrett","artist":"Anonym","date":"1690–1710","place":"Niederlande (Amsterdam)","game":"Verkeer (verwandt mit Backgammon), Schach, Mühle","medium":"Nussbaum mit Einlagen aus Olivenholz, Ebenholz, Buchsbaum und Bein; Kupferbeschläge","size":"Geschlossen 5,8 × 5,8 cm (offen 11,6 cm)","credit":"","p":["Ein kaum sechs Zentimeter großes Spielbrett, das sich wie eine Schachtel öffnet. Außen sind ein Schachbrett und ein Mühlebrett, innen ein Brett für Verkeer, eine niederländische Verwandte des Backgammon. Es schließt mit Kupferscharnieren und einem winzigen Haken.","Darin liegen noch ein Würfel, neun Steine aus Bein, vier aus Ebenholz und drei Münzchen. Die Inventarnummer weist darauf hin, dass es wohl zur Ausstattung des Puppenhauses von Petronella Oortman gehört. So klein es ist, die Holzeinlagen sind sorgfältig und wie bei einem echten Brett gebaut."],"spots":[["Der Würfel","Ein Würfel nicht größer als ein Reiskorn."],["Die Beinsteine","Runde weiße Steine aus Bein."],["Die Ebenholzsteine","Schwarze Steine aus Ebenholz."],["Die Zungen","Dreiecke aus hellem und dunklem Holz."],["Die Scharniere","Kupferscharniere zum Zusammenklappen."],["Der Haken","Ein winziger Kupferhaken zum Schließen."]]},"silverbd":{"title":"Silbernes Miniatur-Spielbrett mit Steinen","artist":"Frederik van Strant II","date":"1739","place":"Niederlande (Amsterdam)","game":"Dame, Mühle","medium":"Silber","size":"5,4 × 5,4 cm","credit":"","p":["Ein Silberbrett von nur 5,4 Zentimetern Seitenlänge: 64 Felder, ein hochgezogener Rand und ein Ring zum Aufhängen. Die dunklen Felder sind fein schraffiert graviert, die Rückseite trägt die Linien für das Mühlespiel.","Es trägt das Amsterdamer Stadtzeichen, den Jahresbuchstaben E für 1739 und die Marke des Silberschmieds Frederik van Strant II. Fünfzehn Damesteine sind erhalten, acht mit einer Blume, sieben mit einem Kreis verziert. Wohl eine Silberminiatur für ein Puppenhaus oder einen Schaukasten."],"spots":[["Blumensteine","Steine mit eingeprägter Blume."],["Kreissteine","Steine mit einem Kreis."],["Der Ring","Ein Ring an der Ecke des Bretts."],["Gravierte Felder","Dunkle, fein schraffierte Felder."],["Glatte Felder","Helle, glatt polierte Felder."],["Der Rand","Der hochgezogene Rand ringsum."]]},"schaak1550":{"title":"Schachspiel mit Reiterfiguren","artist":"Anonym","date":"1550","place":"Deutschland","game":"Schach","medium":"Buchsbaum und Nadelholz","size":"Größte Figur 10,5 cm hoch","credit":"","p":["Jede Figur steht auf einem gedrechselten Fuß mit einem Gitter aus Fleurons und ist mit Reitern und Pferden geschnitzt. Könige und Königinnen reiten Pferde oder Maultiere, als zögen sie zur Jagd.","Laut Museumsdatensatz reitet der schwarze König ein steigendes Pferd, das einen Drachen niedertritt, und trägt eine Kette, die an den Orden vom Goldenen Vlies erinnert – vielleicht Karl V. Eine Königin sitzt im Damensitz auf einem Maultier, einen Falken auf der Hand. Ganz rechts zeigt eine komische Figur einen Affen auf dem Rücken eines Mannes."],"spots":[["Der König","Ein gekrönter, bärtiger König zu Pferd."],["Die Königin","Eine Königin im Damensitz auf einem Maultier, mit Falke."],["Die Affenfigur","Ein Affe auf dem Rücken eines Mannes."],["Eine komische Figur","Ganz links reitet ein Mann auf einem anderen."],["Wesen unter den Hufen","Drachen und Tiere unter den Hufen."],["Die Füße","Gedrechselte Füße mit Fleurons."]]},"kraaij":{"title":"Männer und Frauen beim Brettspiel im Wohnzimmer","artist":"Anonym","date":"1900–1910","place":"Wohl Niederlande","game":"Backgammon","medium":"Kollodium-Auskopierabzug","size":"8,0 × 11,1 cm","credit":"","p":["Ein Blatt aus einem Familienalbum, das auch Fotos der Weinhändler Kraaij & Co., Bordeaux–Amsterdam, enthält. In einem Wohnzimmer mit Kronleuchter sitzen Männer und Frauen, wohl Familie und Freunde, am Tisch.","Auf dem Tisch liegt ein aufgeklapptes Kastenbrett, und die Frauen auf beiden Seiten halten je einen Würfelbecher. Der Museumsdatensatz sagt „ein Brettspiel“, doch Kasten und Becher deuten wohl auf Backgammon. Kaffeetassen daneben und ein Vogelkäfig dahinter zeigen einen gemütlichen Abend zu Hause."],"spots":[["Das Kastenbrett","Ein aufgeklappter Kasten als Spielbrett."],["Der linke Becher","Der Becher der Frau mit Brille."],["Der rechte Becher","Die Frau im gepunkteten Kleid will würfeln."],["Der Vogelkäfig","Ein Vogelkäfig auf einem Ständer dahinter."],["Der Kronleuchter","Lampen mit Glasschirmen von der Decke."],["Der stehende Mann","Rechts, er blickt aufs Spiel."]]},"braekel":{"title":"Alter Mann und alte Frau beim Damespiel","artist":"Ferdinand De Braekeleer (d. Ä.)","date":"1862","place":"Belgien (Antwerpen)","game":"Dame","medium":"Radierung","size":"21,8 × 16,5 cm","credit":"","p":["Eine Radierung des Antwerpener Malers De Braekeleer (1792–1883), unten links signiert „Ferdinand De Braekeleer Antwerpen 1862“. In einer alten Küche mit Herd sitzen ein alter Mann und eine alte Frau an einem Tischchen.","Runde Steine stehen auf dem Brett; er greift einen, sie öffnet die Hand, als widerspräche sie. Am Boden liegt ein Hut, auch ein paar Steine sind hinuntergefallen. Auf dem Bord stehen Teller, durchs Fenster sieht man Häuser."],"spots":[["Brett und Steine","Das Brett mit runden Steinen auf dem Tisch."],["Der alte Mann","Vorgebeugt greift er einen Stein."],["Die alte Frau","Mit Haube, sie gestikuliert beim Reden."],["Der Hut","Der Hut des Mannes am Boden."],["Die Signatur","„Ferdinand De Braekeleer Antwerpen 1862“."],["Die Teller","Große Teller auf dem Bord über dem Herd."]]},"billiard":{"title":"Billard","artist":"Nach H. W. Bunbury (anonymer Stecher)","date":"1780","place":"England (London)","game":"Billard","medium":"Radierung und Punktiermanier","size":"30,0 × 39,1 cm","credit":"","p":["Ein Blatt nach dem englischen Karikaturisten Henry William Bunbury, 1780 in London bei Watson & Dickinson erschienen. Laut Museum ist es Nummer vier einer Folge.","Zwei Männer spielen Billard, die anderen schauen mit angehaltenem Atem zu. Einer beugt sich über den Tisch zum Stoß, ein anderer trägt sein Queue über der Schulter. An der Wand hängen ein Queueständer und zwei runde Zählscheiben. Das Museum bemerkt, dass der Tisch dreieckig zu sein scheint."],"spots":[["Tisch und Kugeln","Der bespannte Tisch mit seinen Kugeln."],["Der Zielende","Über den Tisch gebeugt zum Stoß."],["Der Mann mit dem Queue","Er wartet mit seinem langen Queue."],["Die Zählscheiben","Zwei runde Scheiben an der Wand, wohl zum Zählen."],["Der Queueständer","Eine Reihe Queues an der Wand."],["Die zwei Lachenden","Zwei Zuschauer rechts, die zusammen lachen."]]},"baizi":{"title":"Hundert Kinder (Ausschnitt)","artist":"Xu Yanghong","date":"18. Jahrhundert","place":"China","game":"Weiqi (Go)","medium":"Querrolle; Tusche (und leichte Farben) auf Papier","size":"29,8 × 526 cm (ganze Rolle)","credit":"","p":["Eine Go-Szene aus einer über fünf Meter langen Querrolle des chinesischen Berufsmalers Xu Yanghong. In einem Garten spielen hundert Kinder, musizieren, lesen und schreiben. „Hundert Kinder“ ist ein wichtiges Thema der asiatischen Kunst und steht für Kinderreichtum und das Gedeihen der Familie.","Die Rolle ist auch durch eine spätere Kopie des japanischen Meisters Tani Bunchō bekannt, die dasselbe Museum besitzt. Neben Bananenblättern und einem Gelehrtenstein sitzen Kinder um ein Go-Brett auf einem niedrigen Gestell; zwei spielen, Steinschalen in der Hand, die anderen schauen zu."],"spots":[["Das Brett","Ein Go-Brett auf niedrigem Gestell mit Steinen."],["Das setzende Kind","In blauer Jacke, die Hand in der Steinschale."],["Der andere Spieler","In Weiß, über das Brett gebeugt."],["Hände hinter dem Kopf","Ein Kind, das von hinten zuschaut."],["Der Gelehrtenstein","Ein großer, durchlöcherter Stein."],["Der Federfächer","Ein Kind links mit einem Federfächer."]]},"schenkcards":{"title":"Zwei Chinesinnen beim Kartenspiel","artist":"Pieter Schenk (II)","date":"1727–1775","place":"Niederlande (Thema: China)","game":"Kartenspiel","medium":"Radierung","size":"16,5 × 26,2 cm","credit":"","p":["Ein Blatt aus dem ersten Teil der „Neu erfundenen Chinesen“, einem Album chinesisch anmutender Figuren und Landschaften des Amsterdamer Stechers und Verlegers Pieter Schenk des Jüngeren. Es ist Chinoiserie, die in Europa modische Vorstellung von China.","Laut Museumsdatensatz spielen zwei Chinesinnen in einem Garten Karten, während von rechts eine Frau mit vollem Tablett kommt. Die Karten auf dem Tisch sehen wie europäische Spielkarten aus. Links ruht ein Hase auf einem Gestell, auf dem Fluss liegt ein Segelboot."],"spots":[["Die Karten","Ausgebreitete Karten; sie wirken europäisch."],["Die Frau links","Karten in der Hand, sie schaut ihre Partnerin an."],["Die Frau rechts","Sie legt eine Karte."],["Die Frau mit Tablett","Sie bringt ein Tablett voller Speisen."],["Der Hase","Auf einem Gestell links."],["Das Segelboot","Ein Boot auf dem Fluss."]]},"gosaucer":{"title":"Untertasse mit Go-Spielern","artist":"Anonym","date":"1725–1735","place":"China","game":"Go (Weiqi)","medium":"Porzellan mit Aufglasurfarben und Vergoldung","size":"Durchmesser 16,4 cm","credit":"","p":["Eine chinesische Untertasse, bemalt in den sanften Aufglasurfarben der Famille rose. Unten eine Marke aus Pinsel, Ruyi-Zepter und Tuschestab in einem Doppelkreis. Die Museumsdatensätze beschreiben die Figuren teils als Mann und Frau beim Go, teils als drei Frauen, von denen zwei spielen.","In einem Raum steht ein Go-Brett auf einem Tisch; zwei Spielende setzen einander gegenüber Steine, eine dritte Person schaut stehend zu. Auf dem Tisch gelbe Steinschalen, dahinter ein Gestell mit Blumenvase, rechts ein großer blauer Topf."],"spots":[["Das Brett","Ein Go-Brett mit Steinen auf dem Tisch."],["Die Person links","In Blasslila, an den Tisch gelehnt."],["Die Person rechts","In Rosa, sie setzt einen Stein."],["Die Zuschauerin","Stehend dahinter."],["Die Vase","Eine Blumenvase auf einem Gestell."],["Der blaue Topf","Ein großer Topf rechts."]]},"cheetham":{"title":"Eine kleine Kartenrunde (in Russland)","artist":"Anonym","date":"1903–1904","place":"Russland","game":"Kartenspiel","medium":"Gelatine-Silber-Auskopierabzug","size":"9,2 × 11,5 cm","credit":"","p":["Aus dem Album der englischen Familie Cheetham, die in Russland lebte; der Karton trägt auf Englisch „a little card-party“. Laut Museum sind es wohl englische Freunde zu Besuch bei Joseph Cheetham.","In einem tapezierten Zimmer sitzen drei Menschen an einem Tisch mit geblümter Decke, die Karten aufgefächert. Zwei Kerzenleuchter stehen darauf, und die Frau in der Mitte lacht, während sie ihr Blatt ausbreitet. Wohl ein entspannter Moment mit Landsleuten in der Fremde."],"spots":[["Das Blatt des linken Mannes","Die Karten des Bärtigen."],["Das Blatt der Frau","Die Frau in der Mitte fächert ihre Karten."],["Der Mann rechts","Vorgebeugt, Karten in der Hand."],["Die Leuchter","Zwei Kerzenleuchter auf dem Tisch."],["Die Tischdecke","Eine große Decke mit Blumen und Mustern."],["Die Beschriftung","„a little card-party“ auf dem Karton."]]},"problem":{"title":"Das Problem (Stereofoto)","artist":"Anonym","date":"1852–1863","place":"Unbekannt","game":"Schach","medium":"Stereofotografie, koloriert","size":"8,4 × 17,4 cm","credit":"","p":["Der englische Titel lautet „The Problem“. Zwei Gestalten mit weißen Perücken und Kleidung im Stil des 18. Jahrhunderts spielen an einem verzierten Tisch Schach, als koloriertes Stereobildpaar. Auf der Rückseite steht handschriftlich „Simons“.","Der Jüngere hält sich mit beiden Händen die Wangen und starrt aufs Brett, der Ältere gegenüber grinst. Wohl eine gestellte, theaterhafte Szene, in der man sofort sieht, wer das Problem hat. Zu ihren Füßen liegt ein Hund."],"spots":[["Brett und Figuren","Brett und Figuren auf dem verzierten Tisch."],["Der Grübelnde","Den Kopf in beiden Händen, starrt er aufs Brett."],["Der Grinsende","Der Ältere im blauen Rock, lächelnd."],["Der Hund","Ein Hund zu ihren Füßen."],["Der rote Vorhang","Der kolorierte Vorhang dahinter."],["Das zweite Bild","Die rechte Ansicht; im Stereoskop gewinnt sie Tiefe."]]},"tarocco":{"title":"Zehn Karten aus einem Tarockspiel","artist":"Anonym (wohl nach Giuseppe Maria Mitelli)","date":"1660–1718","place":"Italien (Bologna)","game":"Tarocchi (Kartenspiele mit Trümpfen)","medium":"Radierung und Kupferstich, teils hellbraun handkoloriert","size":"Zehn Karten auf einem Untersatz","credit":"","p":["Zehn Karten aus einem Bologneser Tarockspiel, nebeneinander auf einen Karton geklebt. Das Tarock diente zunächst nicht dem Wahrsagen, sondern Kartenspielen mit Trümpfen. Oben links ist eine Titelkarte; das Museum vermutet im Bildnis den Künstler Mitelli.","Die obere Reihe zeigt vier Figuren, darunter einen gekrönten Mann und einen Reiter; die untere die Sechs bis Zehn der Farbe Münzen, jede mit so vielen Münzen wie ihr Wert. Die gedruckten Linien sind teils hellbraun laviert."],"spots":[["Die Titelkarte","Oben links: ein gerahmtes Bildnis und eine Inschrift."],["Der gekrönte Mann","Eine gekrönte Figur mit Zepter."],["Die stehende Frau","Eine gekrönte Frau mit Becher."],["Der Reiter","Eine Karte mit einer Figur zu Pferd."],["Münzen-Zehn","Unten links: zehn Münzen."],["Münzen-Sechs","Unten rechts: sechs Münzen."]]},"kindtegel":{"title":"Fliesen mit spielenden Kindern","artist":"Anonym","date":"1680–1730","place":"Niederlande","game":"Kinderspiele (Stelzen, Schaukel u. a.)","medium":"Fayence (Delfter Fliesen), blau bemalt","size":"107 × 80 cm (48 Fliesen)","credit":"","p":["Ein Feld aus achtundvierzig Fliesen, acht hoch und sechs breit. Jede zeigt zwei spielende Kinder, klein in Blau gemalt, mit einem „Spinne“ genannten Ornament in jeder Ecke.","Ein Kind läuft auf Stelzen, ein anderes wird auf der Schaukel angestoßen, andere hocken über etwas am Boden: Jede Fliese zeigt ein anderes Spiel. Solche „Kinderspiel“-Fliesen waren in den Niederlanden beliebt und wurden wohl in Küchen und um Kamine an die Wand gesetzt."],"spots":[["Die Stelzen","Ein Kind auf Stelzen."],["Die Schaukel","Ein Kind wird auf der Schaukel angestoßen."],["Ein Bodenspiel","Kinder hocken spielend über etwas am Boden."],["Die Spinnen","Die kleinen Eckornamente."],["Achtundvierzig Fliesen","Acht Reihen zu sechs Fliesen."],["Die letzte Fliese","Die Fliese in der rechten unteren Ecke."]]},"dammolen":{"title":"Miniaturbrett für Dame und Mühle","artist":"Anonym","date":"1740–1760","place":"Niederlande (Amsterdam)","game":"Dame, Mühle","medium":"Nussbaum mit heller Füllmasse","size":"4,2 × 4,0 × 1,5 cm","credit":"","p":["Ein winziges Nussbaumbrett von etwa vier Zentimetern. Fast quadratisch und mit hochgezogenem Rand, dient es auf einer Seite als Damebrett, auf der anderen als Mühlebrett.","Auf der Dameseite sind die Felder ausgestochen und mit heller Masse gefüllt, sodass ein Schachbrettmuster mit dem Holz entsteht; auf der Mühleseite sind die eingeritzten Linien mit derselben Masse gefüllt. So klein, war es wohl für ein Puppenhaus bestimmt."],"spots":[["Gefüllte Felder","Ausgestochene, hell gefüllte Felder."],["Holzfelder","Felder im blanken Nussbaum."],["Der Rand","Der hochgezogene Rand ringsum."],["Die vordere Ecke","Die uns nächste Ecke."],["Die Dicke","Die 1,5 cm hohe Seitenkante."],["Die hintere Reihe","Die hinterste Feldreihe."]]},"karelpiece":{"title":"Damestein mit Bildnis Karls des Großen (Hälfte)","artist":"Anonym","date":"1525–1575","place":"Deutschland (Nürnberg)","game":"Dame oder Puff","medium":"Buchsbaum","size":"Durchmesser 5,3 cm","credit":"","p":["Eine Seite eines aus Buchsbaum geschnitzten Spielsteins. In der Mitte ein Profil im Lorbeerkranz, ringsum die Inschrift „CAROLVS. MAGNVS. IMPER. AVGVST.“ (Karl der Große, Kaiser).","Das Museum besitzt über ein Dutzend gleichartige Steine, jeder mit einem Kaiser oder einer Kaiserin vom alten Rom bis ins Mittelalter: Tiberius, Agrippina, Ludwig der Fromme, Otto und andere. Wohl ein Luxusspiel, als Galerie der Herrscher gedacht."],"spots":[["Das Profil","Karls Profil im Lorbeerkranz."],["Der Kranz","Der Lorbeerring um das Bildnis."],["CAROLVS","Die Worte „CAROLVS. MAGNVS“ oben."],["AVGVST","Die Worte „IMPER. AVGVST“ links."],["Der Stern","Ein kleiner Stern als Trenner."],["Der Rand","Der gestufte Rand des Steins."]]},"vdberge":{"title":"Das holländische Spiel, das schöne Leben! (Kartenspiel)","artist":"Pieter van den Berge (Entwurf und Verlag)","date":"1694–1737","place":"Niederlande (Amsterdam)","game":"Karten","medium":"Radierung, à la poupée rot, blau und grün gedruckt","size":"27,3 × 17,0 cm","credit":"","p":["Eine Satire des Amsterdamer Grafikers und Verlegers Van den Berge mit dem Titel „LE JEU HOLLANDOIS. LA BELLE VIE!“. Laut Museum spielen Männer in einer Schenke Karten, während Teufel neben einem seufzenden Mann mit erhobenem Glas und unter dem Tisch sein Geld gewinnen.","In den niederländischen Versen darunter klagt der sorglose Lebemann, Hunde- und Hahnenkämpfe, Karten und Würfel hätten sein Geld zerschmelzen lassen. Zu beiden Seiten locken ihn zwei Teufel auf Deutsch, bei Würfel und Karten lustig zu sein. Auch das Bild an der Rückwand zeigt Hunde- und Hahnenkämpfe."],"spots":[["Der Mann mit dem Glas","Der Lebemann in großer Perücke hebt sein Glas."],["Das Blatt","Aufgefächerte Karten in seiner Hand."],["Der Teufel links","Ein grinsender Teufel hinter ihm."],["Der Teufel unterm Tisch","Er rafft die zu Boden gefallenen Münzen."],["Das Kampfbild","Ein Gemälde mit Hunde- und Hahnenkämpfen."],["Titel und Vers","„LE JEU HOLLANDOIS“ und die Klage des Lebemanns."]]},"crespi":{"title":"Kinder beim Würfelspiel","artist":"Giuseppe Maria Crespi","date":"1675–1747","place":"Italien","game":"Würfel","medium":"Radierung","size":"22,5 × 15,1 cm","credit":"","p":["Eine eigenhändige Radierung des Bologneser Malers Crespi. Laut Museum spielen vier Kinder auf der Straße mit Würfeln; darunter steht ein dreizeiliger italienischer Vers.","Ein hockendes Kind hat gerade die Würfel auf den Boden geworfen, die drei anderen schauen zu. Der Vers spricht von Knochen (Würfeln) und Zahlen, einem kurzen Spiel und schwindendem Geld – wohl eine Warnung vor dem Glücksspiel selbst beim Kinderspiel."],"spots":[["Die Würfel","Kleine Würfel am Boden."],["Das hockende Kind","Es hat gerade gewürfelt."],["Das stehende Kind","Es blickt auf den Wurf."],["Das Kind rechts","Auf dem Boden sitzend schaut es zu."],["Das Kind dahinter","Es lugt hinter den anderen hervor."],["Der Vers","Drei Zeilen italienischer Vers."]]},"epinal":{"title":"Großes Gänsespiel (Épinal)","artist":"Pellerin & Cie (Épinal)","date":"1791–1900","place":"Frankreich (Épinal)","game":"Gänsespiel (Würfelwettlauf)","medium":"Holzschnitt, gelb, rot, grün und blau koloriert; Text im Buchdruck","size":"39,8 × 59,0 cm","credit":"","p":["Ein Farbbogen der Bilderdruckerei Pellerin in Épinal in Ostfrankreich, französisch überschrieben „GRAND JEU DE L’OIE“. Laut Museum zeigt eine Spirale von 63 Feldern Gänse, andere Tiere und Figuren, in der Mitte stehen der niederländische Titel „GANZENBORD!“ und die Regeln.","Nach den Regeln würfelt man mit zwei Würfeln; wer auf eine Gans kommt, zieht noch einmal so weit. Die Brücke (6) führt nach 12, das Wirtshaus (19) kostet zwei Runden, am Brunnen (31) wartet man, bis ein anderer kommt, das Labyrinth (42) schickt zurück nach 30 und der Tod (58) an den Anfang. Gewonnen hat, wer genau auf 63 kommt. Zu beiden Seiten stehen Spielmarken zum Ausschneiden."],"spots":[["63: die Gans","Das Ziel, 63: eine Gans auf dem Teich."],["Die Regeln","Die niederländischen Regeln in der Mitte."],["Marken zum Ausschneiden","Runde, nummerierte Marken an beiden Seiten."],["Der Titel","„GRAND JEU DE L’OIE“ oben."],["Spielende Kinder","Kinder in der linken unteren Ecke."],["Der Verlag","„PELLERIN & Cie“ oben links."]]},"matham":{"title":"Paar beim Tricktrack","artist":"Jacob Matham (Verleger), Verse von Simon Sovius","date":"1621","place":"Niederlande (Haarlem)","game":"Tricktrack (verwandt mit Backgammon)","medium":"Kupferstich","size":"17,9 × 20,0 cm","credit":"","p":["Das dritte Blatt einer vierteiligen Folge, verlegt vom Haarlemer Stecher und Verleger Matham. Laut Museum spielt ein elegant gekleidetes Paar an einem Tischchen Tricktrack um Geld; der Beutel liegt auf dem Tisch, die Dame hält die Würfel.","Die langen Zungen und die hellen und dunklen Steine des Bretts sind scharf gestochen. Darunter stehen lateinische und niederländische Verse; die niederländischen warnen, nicht nur das Übermaß des Trinkens wecke unkeusche Gedanken, auch Spiel und Würfeln seien gegen jeden Nutzen. Hinten hebt ein Junge ein Weinglas."],"spots":[["Das Brett","Ein Tricktrackbrett mit Zungen und Steinen."],["Der ziehende Mann","Der Mann mit Hut greift übers Brett."],["Die Dame mit den Würfeln","Mit großer Halskrause, die Würfel in der Hand."],["Der Junge mit dem Glas","Er hebt hinten ein Weinglas."],["Der Beutel","Der Geldbeutel mit den Einsätzen auf dem Tisch."],["Die Verse","Mahnende Verse auf Latein und Niederländisch."]]},"jardin":{"title":"Drei Männer beim Kartenspiel am Gartentisch, mit Zuschauer (Frankreich)","artist":"Anonym (ein französischer Amateurfotograf)","date":"1900–1910","place":"Frankreich","game":"Kartenspiel","medium":"Albuminabzug","size":"11,8 × 17,2 cm","credit":"","p":["Aus dem Album eines französischen Amateurfotografen, das auch Aufnahmen einer Familie, der Brennerei Delizy & Doistau, des Militärs und von Sehenswürdigkeiten in Frankreich enthält.","Im Schatten eines Kiesgartens spielen drei Männer an einem kleinen Tisch Karten, während ein älterer Mann mit weißem Bart hinter ihnen steht und zuschaut. Karten liegen auf dem Tisch, der Mann mit Strohhut betrachtet sein Blatt. Wohl ein entspannter Moment unter Familie oder Freunden."],"spots":[["Karten auf dem Tisch","Ausgespielte Karten."],["Der Zuschauer","Der ältere Mann mit weißem Bart, stehend."],["Der Mann mit Strohhut","In der Mitte, er betrachtet sein Blatt."],["Der Mann rechts","Im dunklen Rock, Karten in der Hand."],["Der Mann links","In heller Jacke."],["Der Garten","Kies und Büsche des Gartens."]]},"lamplight":{"title":"Kartenspielende Menschen (unter der Lampe)","artist":"Anonym","date":"1900–1910","place":"Unbekannt","game":"Kartenspiel","medium":"Gelatine-Silber-Entwicklungsabzug","size":"7,5 × 10,0 cm","credit":"","p":["Ein kleines Foto aus einem Album, vom Museum „Kartenspielende Personen“ betitelt. Fotograf und Ort sind unbekannt.","Im Licht einer von der Decke hängenden Petroleumlampe sitzen eine Frau im gestreiften Kleid, ein Mädchen und einige Jungen an einem Tisch mit Fransendecke und fächern ihre Karten auf. In einem dunklen Raum zu fotografieren war schwierig; man wollte wohl einen Familienabend festhalten."],"spots":[["Die Fransendecke","Eine gemusterte Decke mit Fransen."],["Die Lampe","Eine Petroleumlampe von der Decke."],["Die Frau in Streifen","Sitzend im weiß gestreiften Kleid."],["Das Blatt der Frau","Die Karten, die sie wie einen Fächer hält."],["Das Blatt des Mädchens","Das Mädchen in der Mitte breitet ihr Blatt aus."],["Der Junge rechts","Vorgebeugt, Karten in der Hand."]]},"borduur":{"title":"Bestickte Spieltischplatte mit Kartenspielern","artist":"Anonym","date":"1700–1725","place":"Unbekannt","game":"Kartenspiel","medium":"Gros- und Petit-point-Stickerei in farbiger Wolle und Seide","size":"100 × 185 cm","credit":"","p":["Stickerei von der Platte eines Klappspieltischs, in vielfarbiger Wolle und Seide, mit gröberem Gros point und feinerem Petit point. In einer Form mit abgeschrägten Ecken läuft ein Rahmen aus Voluten und Blumen.","In der Landschaft in der Mitte sitzen zwei Damen und ein Herr kartenspielend um einen Tisch. Laut Museumsdatensatz liegen darauf eine Geldbörse, Karten und weiteres Spielgerät. Ein Kartentisch, passend mit einer Kartenpartie geschmückt."],"spots":[["Der Tisch","Der grüne Tisch mit Börse und Karten."],["Der Herr","Ein Mann mit Hut, links sitzend."],["Die Dame in der Mitte","Eine Dame hinter dem Tisch."],["Die Dame rechts","Eine Dame in Blau."],["Die Bäume","Bäume hinter den Figuren."],["Der Rahmen","Ein Rahmen aus Voluten und Blumen."]]},"piquet":{"title":"Tuch mit aufgedrucktem Piquetspiel","artist":"Anonym","date":"1725–1750","place":"Unbekannt","game":"Piquet (Kartenspiel)","medium":"Leinen, rot und violett bedruckt","size":"73,0 × 82,5 cm","credit":"","p":["Ein Leinentuch für den Spieltisch, ganz in Rot und Violett mit den Dingen eines Kartenspiels bedruckt. Der Museumsdatensatz beschreibt es auch als Taschentuch.","Karten für Piquet, das mit 32 Karten von der Sieben bis zum Ass gespielt wird, liegen am Rand und in der Mitte verstreut, mit einer Börse in der Mitte und Spielmarken ringsum. Die Bildkarten folgen dem Pariser Bild, mit Namen wie Caesar, Argine und Hogier."],"spots":[["Die Börse","Die Einsatzbörse in der Mitte."],["Die Bildkarten","Könige und Damen des Pariser Bildes."],["Die Spielmarken","Runde Spielmarken."],["Der Kartenrand","Ein Band aus Karten rings ums Tuch."],["Verdeckte Päckchen","Päckchen mit sichtbarer Rückseite."],["Das versiegelte Päckchen","Ein versiegeltes Kartenpäckchen unten rechts."]]},"schaakglas":{"title":"Kelchglas mit zwei Schachspielern","artist":"Anonym","date":"1815–1830","place":"Unbekannt","game":"Schach","medium":"Klares farbloses Glas, Radgravur","size":"Höhe 13,7 cm","credit":"","p":["Ein klares Kelchglas, Bild und Schrift mit einem kleinen rotierenden Rad geschnitten. An einem Tischchen mit zwei Kerzen sitzen sich zwei Männer am Schachbrett gegenüber.","Der linke mit Brille raucht Pfeife, der rechte beugt sich übers Brett; auf dem Tisch steht ein Weinglas. Ringsum steht französisch: Die Züge zu kennen ist eine ganz einfache Sache; das Spiel zu kennen ist eine Frucht des Genies."],"spots":[["Das Schachbrett","Das Brett mit seinen Figuren."],["Der Mann mit Pfeife","Links, mit Brille und Pfeife."],["Der vorgebeugte Mann","Rechts, aufs Brett spähend."],["Die Kerzen","Zwei Kerzen hinter dem Brett."],["Das Weinglas","Ein Glas auf dem Tisch."],["Die Inschrift","Französisch eingravierte Worte."]]},"arlequin":{"title":"Harlekins Lottospiel","artist":"Anonym (Verlag Mindermann & Co.)","date":"1818–1845","place":"Niederlande (Amsterdam)","game":"Lotto / Laufspiel","medium":"Kupferstich, handkoloriert, auf Karton geklebt","size":"Unbekannt","credit":"","p":["Ein Spielbogen, dessen Spielfeld Harlekin selbst ist, breitbeinig stehend. Quadratische Felder von 1 bis 32 laufen über sein grünes Kostüm und zwischen seinen Beinen. Unten stehen der Titel „Arlequin’s Lotto-Spel“ und der Name von Mindermann & Co. in Amsterdam.","Er trägt eine Netzmaske und hält einen Hut und etwas wie ein Holzschwert. Einige Felder sind mit „HW“ oder „P“ bezeichnet. Der handkolorierte Stich wurde auf Karton geklebt, wohl um als Spielbrett zu dienen."],"spots":[["Die Netzmaske","Das Netz über seinem Gesicht."],["Feld 1","Der Start unter seinem linken Bein."],["Ein HW-Feld","Ein mit „HW“ bezeichnetes Feld."],["P 32","Feld 32 mit „P“."],["Der Titel","„Arlequin’s Lotto-Spel“ unten."],["Der Hut","Der Hut in seiner rechten Hand."]]},"vicaire":{"title":"Die Partie des Vikars","artist":"René Gayant (laut Tafel)","date":"1888–1893","place":"Frankreich","game":"Kartenspiel","medium":"Lichtdruck (laut Museum)","size":"10,4 × 15,6 cm","credit":"","p":["Eine Tafel aus dem Bulletin du Photo-Club de Paris mit dem Titel „La partie du Vicaire“. Am Rand steht „Phototype René Gayant“ und „Héliogravure Lemercier“; das Foto stammt also wohl von Gayant, der Druck von Lemercier. Im Buch war sie quer eingebunden.","In einer Küche voller Töpfe und Pfannen sitzt ein Priester in schwarzer Soutane am Tisch und betrachtet seine Karten, auch der Mann gegenüber hält ein Blatt. Ein Mann mit Mütze stützt das Kinn in die Hand, ein junger Mensch, die Hand am Ohr, schaut zu. Licht und Bildaufbau wie ein Gemälde passen zu einem Club der Kunstfotografie."],"spots":[["Die Karten des Vikars","Die Karten, die der Priester betrachtet."],["Der Vikar","In schwarzer Soutane mit weißem Kragen."],["Der Mann mit Karten","Mit Lockenkopf, den Blick auf dem Blatt."],["Der junge Zuschauer","Die Hand an der Wange, er schaut zu."],["Der Mann mit Mütze","Das Kinn in die Hand gestützt."],["Die Küchenwand","Töpfe und Kellen an der Wand."]]},"israels":{"title":"Die Schachspieler","artist":"Isaac Israels","date":"1875–1922","place":"Niederlande","game":"Schach","medium":"Pastell","size":"40,0 × 57,5 cm","credit":"","p":["Ein Pastell des niederländischen Malers Isaac Israels (1865–1934), bekannt für schnelle, lebendige Szenen aus dem Amsterdamer Stadtleben. In einem Raum mit hellem Fenster sitzen Männer um ein Schachbrett.","Die beiden vorn stützen Wange oder Kinn in die Hand und starren aufs Brett, während sich ein Mann mit Mütze von hinten vorbeugt. Die Figuren sind nicht ausgeführt, sondern als Farbtupfer gesetzt; eine lange Bedenkzeit scheint zu vergehen."],"spots":[["Brett und Figuren","Das Brett; die Figuren sind Farbtupfer."],["Der linke Spieler","Die Wange in der Hand, den Blick aufs Brett."],["Der rechte Spieler","Das Kinn in der Hand, nachdenkend."],["Der Mann mit Mütze","Er beugt sich von hinten vor."],["Das Fenster","Das helle Fenster links."],["Der Stuhl","Ein Stuhl rechts."]]},"louisxi":{"title":"Ludwig XI. und seine Tochter Anne de Beaujeu","artist":"Adrien Joseph Verhoeven-Ball","date":"1866","place":"Belgien (Antwerpen)","game":"Schach","medium":"Druckgrafik (wohl Radierung)","size":"26,4 × 31,3 cm","credit":"","p":["Der Antwerpener Maler Verhoeven-Ball hat dieses Blatt selbst entworfen und gestochen („pinx et sculp“, unten). Der Museumstitel lautet „Ludwig XI. und seine Tochter Anne de Beaujeu spielen Schach“. Eine Zeile unten nennt die zweite Ausstellung der Antwerpener Künstlervereinigung.","Ludwig XI., König von Frankreich im 15. Jahrhundert, sitzt im Pelzmantel am Tisch, seine Tochter Anne stützt das Kinn in die Hand und betrachtet das Brett. Auf dem Tisch stehen Figuren und eine Obstschale, ein Hund liegt am Boden, hinten steht ein bewaffneter Wächter. Wohl eine erdachte Szene des historischen Vaters und seiner Tochter."],"spots":[["Brett und Figuren","Schachbrett und Figuren auf dem Tisch."],["Ludwig XI.","Der König mit Hut und Pelzmantel."],["Anne","Die Tochter, das Kinn in der Hand."],["Der schlafende Hund","Ein schlanker Hund am Boden."],["Der Wächter","Ein bewaffneter Soldat im Dunkel."],["Der Titel","„LOUIS XI ET SA FILLE ANNE DE BEAU-JEU“."]]},"bruining":{"title":"Mönche beim Damespiel","artist":"Tieleman Cato Bruining","date":"1750–1850","place":"Niederlande","game":"Dame","medium":"Radierung","size":"20,6 × 16,8 cm","credit":"","p":["Eine Radierung des niederländischen Grafikers Bruining, unten links bezeichnet „T. Bruining inv. et fecit aqua fort“ (entworfen und radiert). Laut Museum spielen zwei Mönche an einem Tisch Dame.","Hinter ihnen stehen ein dritter Mönch und ein Teufel in Mönchskutte. Neben dem Tisch steht der Tod, ebenfalls als Mönch verkleidet, die Sense hinter dem Rücken versteckt. Die Mönche sind so ins Spiel vertieft, dass sie die Eindringlinge nicht bemerken."],"spots":[["Das Damebrett","Brett und Steine auf dem Tisch."],["Der Tod","In der Kutte, die Sense hinter dem Rücken."],["Die zwei dahinter","Ein dritter Mönch und der Teufel in Kutte."],["Der linke Spieler","Ein Mönch, übers Brett gebeugt."],["Der rechte Spieler","Ein nachdenkender Mönch, die Arme auf dem Tisch."],["Die Signatur","„T. Bruining inv. et fecit aqua fort“."]]},"vanvliet":{"title":"Tricktrackspieler bei Kerzenlicht","artist":"Jan Gillisz. van Vliet","date":"1631–1634","place":"Niederlande (Leiden)","game":"Tricktrack (verwandt mit Backgammon)","medium":"Radierung und Kupferstich","size":"15,2 × 13,4 cm","credit":"","p":["Ein Blatt von Van Vliet, der in Leiden neben Rembrandt arbeitete. Laut Museum spielen zwei Gestalten in einem dunklen Raum mit Himmelbett links Tricktrack, rechts stehen ein Mann und eine Frau.","Ein Mann in Schwarz beugt sich, uns den Rücken zugewandt, tief übers Brett, sein Gegner lacht, die Hand am Brettrand. Zungen und Steine sind deutlich zu sehen. Die Lichtquelle ist verborgen, doch nur Brett und Gesichter sind erhellt – wohl eine nächtliche Partie."],"spots":[["Das Brett","Ein Tricktrackbrett mit Zungen und Steinen."],["Der lachende Spieler","Lachend, die Hand am Brettrand."],["Der Vorgebeugte","In Schwarz, mit dem Rücken zu uns, übers Brett gebeugt."],["Der Mann mit Hut","Hinten stehend, mit breitkrempigem Hut."],["Die Gestalt mit Halskrause","Rechts, eine Hand erhoben."],["Die Bettvorhänge","Vorhänge des Himmelbetts links."]]},"hermans":{"title":"Zwei Frauen und ein Mädchen am Schachbrett","artist":"François Hermans (Atelier)","date":"1857–1895","place":"Niederlande (Rotterdam)","game":"Schach","medium":"Albuminabzug (Carte de visite)","size":"10,1 × 6,2 cm","credit":"","p":["Eine Fotografie im Carte-de-visite-Format aus einem Familienalbum, rückseitig mit dem Ateliernamen „François Hermans / Hang 421 / Rotterdam“ bedruckt. Vermutlich ein im Atelier aufgenommenes Familienandenken.","Auf einem kleinen runden Tisch steht ein Schachbrett; die linke Frau berührt eine Figur, die rechte stützt nachdenklich die Wange in die Hand. Dazwischen steht ein Mädchen und blickt uns geradewegs an. Alle drei mussten während der langen Belichtung stillhalten."],"spots":[["Das Schachbrett","Brett und Figuren auf dem runden Tisch."],["Die ziehende Hand","Die linke Frau berührt eine Figur."],["Das Mädchen","Hinter dem Brett stehend, schaut es uns an."],["Die Nachdenkliche","Die rechte Frau, die Hand an der Wange."],["Der Fußschemel","Ein runder Schemel am Boden."],["Das Fenster","Ein Sprossenfenster hinten rechts."]]}};
